# -*- coding: utf-8 -*-
# Sessions chrono enregistrees, circuits de camp, historique complet, chrono rapide,
# navigation mobile en bas avec bouton Chrono central
# A lancer depuis la racine du dossier pompiers-app : python3 apply_update_7.py
import pathlib

FILES = {}

FILES['backend/prisma/schema.prisma'] = '// Schema Prisma - Application de suivi de camps d\'entrainement\n// Par defaut : SQLite (aucune installation requise).\n// Pour passer sur PostgreSQL en production, remplacer le provider ci-dessous\n// par "postgresql" et adapter DATABASE_URL dans .env\n\ngenerator client {\n  provider = "prisma-client-js"\n}\n\ndatasource db {\n  provider = "sqlite"\n  url      = env("DATABASE_URL")\n}\n\n// Note : pas d\'enum Prisma ici (ExerciseUnit / RecurrenceType) car SQLite ne supporte pas\n// les enums natifs. Les valeurs autorisees ("REPS"/"SECONDS", "DAILY"/"WEEKLY"/"EVERY_N_DAYS")\n// sont validees cote API avec zod.\n\nmodel User {\n  id             String   @id @default(cuid())\n  email          String   @unique\n  passwordHash   String\n  name           String\n  weightKg       Float?\n  heightCm       Float?\n  birthDate      DateTime?\n  sex            String?  // "F" | "M" | "AUTRE" | null, libre / optionnel\n  createdAt      DateTime @default(now())\n\n  memberships    CampMembership[]\n  createdCamps   Camp[]            @relation("CampCreator")\n  createdExos    Exercise[]        @relation("ExerciseCreator")\n  logs           ExerciseLog[]\n  subscriptions  PushSubscription[]\n  badges         UserBadge[]\n  campMessages   CampMessage[]\n  sentMessages   DirectMessage[]   @relation("MessageSender")\n  receivedMessages DirectMessage[] @relation("MessageRecipient")\n  chronoSessions ChronoSession[]\n  circuitLogs    CampCircuitLog[]\n}\n\nmodel Exercise {\n  id          String       @id @default(cuid())\n  name        String\n  description String?\n  unit        String       // "REPS" ou "SECONDS"\n  isCustom    Boolean      @default(false)\n  createdById String?\n  createdBy   User?        @relation("ExerciseCreator", fields: [createdById], references: [id])\n  createdAt   DateTime     @default(now())\n\n  campExercises CampExercise[]\n  logs          ExerciseLog[]\n}\n\nmodel Camp {\n  id          String    @id @default(cuid())\n  name        String\n  description String?\n  code        String    @unique\n  createdById String\n  createdBy   User      @relation("CampCreator", fields: [createdById], references: [id])\n  startDate   DateTime?\n  endDate     DateTime?\n  createdAt   DateTime  @default(now())\n\n  exercises CampExercise[]\n  circuits  CampCircuit[]\n  members   CampMembership[]\n  logs      ExerciseLog[]\n  messages  CampMessage[]\n}\n\n// Consigne d\'un exercice au sein d\'un camp : definie UNIQUEMENT par le createur du camp\n// (la "casquette entraineur"). Tous les membres suivent la meme consigne.\nmodel CampExercise {\n  id             String   @id @default(cuid())\n  campId         String\n  exerciseId     String\n  description    String?  // court descriptif/consigne redige par le createur du camp\n  targetSets     Int      @default(3)\n  targetMode     String   @default("FIXED") // "FIXED" (objectif chiffre) ou "MAX" (a fond, sans cible fixe)\n  targetValue    Int?     // nombre de repetitions OU de secondes vise (voir Exercise.unit) ; inutilise si targetMode = MAX\n  recurrenceType String   @default("DAILY") // "DAILY" | "WEEKLY" | "EVERY_N_DAYS"\n  daysOfWeek     String?  // JSON array ex: "[1,3,5]" (0=dimanche ... 6=samedi), utilise si WEEKLY\n  intervalDays   Int?     // utilise si EVERY_N_DAYS\n  startDate      DateTime @default(now())\n\n  camp     Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n  exercise Exercise @relation(fields: [exerciseId], references: [id])\n  logs     ExerciseLog[]\n\n  @@unique([campId, exerciseId])\n}\n\nmodel CampMembership {\n  id       String   @id @default(cuid())\n  userId   String\n  campId   String\n  joinedAt DateTime @default(now())\n  user     User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  camp     Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, campId])\n}\n\nmodel ExerciseLog {\n  id         String   @id @default(cuid())\n  userId     String\n  campId     String\n  exerciseId String\n  date       DateTime // jour concerne (heure normalisee a minuit)\n  setsDone   Int\n  valueDone  Int      // repetitions ou secondes realisees (moyenne/estimation par serie, cf notes)\n  completed  Boolean  @default(true)\n  createdAt  DateTime @default(now())\n\n  user         User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  camp         Camp          @relation(fields: [campId], references: [id], onDelete: Cascade)\n  exercise     Exercise      @relation(fields: [exerciseId], references: [id])\n  campExercise CampExercise? @relation(fields: [campId, exerciseId], references: [campId, exerciseId])\n\n  @@unique([userId, campId, exerciseId, date])\n}\n\nmodel PushSubscription {\n  id        String   @id @default(cuid())\n  userId    String\n  endpoint  String   @unique\n  p256dh    String\n  auth      String\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel UserBadge {\n  id        String   @id @default(cuid())\n  userId    String\n  badgeKey  String   // identifiant du badge, voir src/utils/badges.ts pour le catalogue\n  earnedAt  DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, badgeKey])\n}\n\n// Discussion de groupe entre les membres d\'un camp\nmodel CampMessage {\n  id        String   @id @default(cuid())\n  campId    String\n  userId    String\n  body      String\n  createdAt DateTime @default(now())\n\n  camp Camp @relation(fields: [campId], references: [id], onDelete: Cascade)\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Message prive entre deux utilisateurs (reserve aux personnes qui partagent au moins un camp)\nmodel DirectMessage {\n  id          String   @id @default(cuid())\n  senderId    String\n  recipientId String\n  body        String\n  createdAt   DateTime @default(now())\n\n  sender    User @relation("MessageSender", fields: [senderId], references: [id], onDelete: Cascade)\n  recipient User @relation("MessageRecipient", fields: [recipientId], references: [id], onDelete: Cascade)\n}\n\n// Seance de circuit training "libre" (construite depuis l\'onglet Chrono, pas liee a un camp).\n// Enregistree une fois terminee, pour alimenter l\'historique d\'activite de l\'utilisateur.\nmodel ChronoSession {\n  id                   String   @id @default(cuid())\n  userId               String\n  name                 String? // nom optionnel donne par l\'utilisateur\n  items                String  // JSON : liste ordonnee des noms d\'exercices du circuit\n  workSeconds          Int\n  restSeconds          Int\n  rounds               Int\n  roundRestSeconds     Int\n  totalDurationSeconds Int\n  completedAt          DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Circuit training defini par le createur d\'un camp (alternative aux exercices individuels).\n// Compose d\'une liste ordonnee d\'exercices avec temps de travail/repos, nombre de tours, etc.\nmodel CampCircuit {\n  id               String   @id @default(cuid())\n  campId           String\n  name             String\n  description      String?\n  items            String   // JSON : [{ "exerciseId": "...", "name": "..." }, ...] ordonne\n  workSeconds      Int\n  restSeconds      Int\n  rounds           Int\n  roundRestSeconds Int\n  recurrenceType   String   @default("DAILY")\n  daysOfWeek       String?\n  intervalDays     Int?\n  startDate        DateTime @default(now())\n\n  camp Camp             @relation(fields: [campId], references: [id], onDelete: Cascade)\n  logs CampCircuitLog[]\n}\n\n// Validation, par un membre, d\'un circuit de camp realise un jour donne\nmodel CampCircuitLog {\n  id              String   @id @default(cuid())\n  userId          String\n  campCircuitId   String\n  campId          String\n  date            DateTime\n  durationSeconds Int\n  completed       Boolean  @default(true)\n  createdAt       DateTime @default(now())\n\n  user        User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  campCircuit CampCircuit @relation(fields: [campCircuitId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, campCircuitId, date])\n}\n'
FILES['backend/src/utils/badges.ts'] = 'import { prisma } from "../lib/prisma";\nimport { toDayStart } from "./recurrence";\n\n// Catalogue des badges disponibles. Purement individuel : aucune comparaison entre utilisateurs.\nexport interface BadgeDefinition {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n}\n\nexport const BADGE_CATALOG: BadgeDefinition[] = [\n  { key: "STREAK_3", name: "3 jours d\'affilee", description: "Une seance realisee chaque jour, 3 jours de suite.", emoji: "🔥" },\n  { key: "STREAK_7", name: "1 semaine reguliere", description: "Une seance realisee chaque jour, 7 jours de suite.", emoji: "🔥" },\n  { key: "STREAK_30", name: "1 mois de regularite", description: "Une seance realisee chaque jour, 30 jours de suite.", emoji: "🏅" },\n  { key: "STREAK_100", name: "100 jours de suite", description: "Une seance realisee chaque jour, 100 jours de suite.", emoji: "🏆" },\n  { key: "TOTAL_10", name: "10 seances", description: "10 seances validees au total.", emoji: "✅" },\n  { key: "TOTAL_50", name: "50 seances", description: "50 seances validees au total.", emoji: "⭐" },\n  { key: "TOTAL_100", name: "100 seances", description: "100 seances validees au total.", emoji: "🌟" },\n  { key: "TOTAL_500", name: "500 seances", description: "500 seances validees au total.", emoji: "💎" },\n];\n\nconst STREAK_THRESHOLDS: [number, string][] = [\n  [100, "STREAK_100"],\n  [30, "STREAK_30"],\n  [7, "STREAK_7"],\n  [3, "STREAK_3"],\n];\n\nconst TOTAL_THRESHOLDS: [number, string][] = [\n  [500, "TOTAL_500"],\n  [100, "TOTAL_100"],\n  [50, "TOTAL_50"],\n  [10, "TOTAL_10"],\n];\n\n// Calcule le plus long "streak" en cours (jours consecutifs avec au moins une seance,\n// tous camps/exercices confondus), en remontant depuis aujourd\'hui ou hier.\nfunction computeGlobalStreak(distinctDates: Set<string>, today: Date): number {\n  const start = toDayStart(today);\n  // Si rien n\'est fait aujourd\'hui, on tolere et on part d\'hier pour ne pas casser la serie\n  // en cours de journee.\n  let cursor = new Date(start);\n  if (!distinctDates.has(cursor.toISOString().slice(0, 10))) {\n    cursor.setUTCDate(cursor.getUTCDate() - 1);\n  }\n  let streak = 0;\n  for (let i = 0; i < 3650; i++) {\n    const key = cursor.toISOString().slice(0, 10);\n    if (!distinctDates.has(key)) break;\n    streak++;\n    cursor.setUTCDate(cursor.getUTCDate() - 1);\n  }\n  return streak;\n}\n\n// Recalcule les stats de l\'utilisateur et attribue tout nouveau badge merite.\n// Appele apres chaque validation de seance (exercice, circuit de camp, ou seance chrono libre).\n// Idempotent (un badge n\'est jamais attribue deux fois).\nexport async function checkAndAwardBadges(userId: string): Promise<BadgeDefinition[]> {\n  const [exerciseLogs, circuitLogs, chronoSessions] = await Promise.all([\n    prisma.exerciseLog.findMany({ where: { userId }, select: { date: true } }),\n    prisma.campCircuitLog.findMany({ where: { userId }, select: { date: true } }),\n    prisma.chronoSession.findMany({ where: { userId }, select: { completedAt: true } }),\n  ]);\n\n  const distinctDates = new Set<string>([\n    ...exerciseLogs.map((l) => l.date.toISOString().slice(0, 10)),\n    ...circuitLogs.map((l) => l.date.toISOString().slice(0, 10)),\n    ...chronoSessions.map((s) => s.completedAt.toISOString().slice(0, 10)),\n  ]);\n  const totalSessions = exerciseLogs.length + circuitLogs.length + chronoSessions.length;\n  const streak = computeGlobalStreak(distinctDates, new Date());\n\n  const earnedKeys = new Set<string>();\n  // On attribue TOUS les paliers deja franchis (pas seulement le plus haut), pour garder\n  // l\'historique des badges obtenus meme si la serie casse ensuite.\n  for (const [threshold, key] of STREAK_THRESHOLDS) {\n    if (streak >= threshold) earnedKeys.add(key);\n  }\n  for (const [threshold, key] of TOTAL_THRESHOLDS) {\n    if (totalSessions >= threshold) earnedKeys.add(key);\n  }\n\n  if (earnedKeys.size === 0) return [];\n\n  const alreadyEarned = await prisma.userBadge.findMany({ where: { userId }, select: { badgeKey: true } });\n  const alreadyEarnedKeys = new Set(alreadyEarned.map((b) => b.badgeKey));\n\n  const newlyEarned = [...earnedKeys].filter((k) => !alreadyEarnedKeys.has(k));\n  if (newlyEarned.length === 0) return [];\n\n  await prisma.userBadge.createMany({\n    data: newlyEarned.map((badgeKey) => ({ userId, badgeKey })),\n  });\n\n  return BADGE_CATALOG.filter((b) => newlyEarned.includes(b.key));\n}\n'
FILES['backend/src/routes/campCircuits.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { toDayStart } from "../utils/recurrence";\nimport { checkAndAwardBadges } from "../utils/badges";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nconst recurrenceSchema = z.discriminatedUnion("recurrenceType", [\n  z.object({ recurrenceType: z.literal("DAILY") }),\n  z.object({ recurrenceType: z.literal("WEEKLY"), daysOfWeek: z.array(z.number().min(0).max(6)).min(1) }),\n  z.object({ recurrenceType: z.literal("EVERY_N_DAYS"), intervalDays: z.number().min(1) }),\n]);\n\nconst circuitSchema = z\n  .object({\n    campId: z.string(),\n    name: z.string().min(1, "Le nom du circuit est requis."),\n    description: z.string().max(500).optional().nullable(),\n    items: z.array(z.object({ exerciseId: z.string().optional(), name: z.string().min(1) })).min(1, "Ajoute au moins un exercice au circuit."),\n    workSeconds: z.number().min(5),\n    restSeconds: z.number().min(0),\n    rounds: z.number().min(1),\n    roundRestSeconds: z.number().min(0),\n  })\n  .and(recurrenceSchema);\n\nasync function assertCoach(userId: string, campId: string) {\n  const camp = await prisma.camp.findUnique({ where: { id: campId } });\n  if (!camp) return { ok: false as const, status: 404, error: "Camp introuvable." };\n  if (camp.createdById !== userId) {\n    return { ok: false as const, status: 403, error: "Seul le createur du camp peut definir les circuits." };\n  }\n  return { ok: true as const };\n}\n\n// Cree un circuit training pour un camp : reserve au createur du camp\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = circuitSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const data = parsed.data;\n\n  const check = await assertCoach(req.userId!, data.campId);\n  if (!check.ok) return res.status(check.status).json({ error: check.error });\n\n  const circuit = await prisma.campCircuit.create({\n    data: {\n      campId: data.campId,\n      name: data.name,\n      description: data.description ?? null,\n      items: JSON.stringify(data.items),\n      workSeconds: data.workSeconds,\n      restSeconds: data.restSeconds,\n      rounds: data.rounds,\n      roundRestSeconds: data.roundRestSeconds,\n      recurrenceType: data.recurrenceType,\n      daysOfWeek: data.recurrenceType === "WEEKLY" ? JSON.stringify(data.daysOfWeek) : null,\n      intervalDays: data.recurrenceType === "EVERY_N_DAYS" ? data.intervalDays : null,\n    },\n  });\n\n  res.status(201).json(circuit);\n});\n\n// Modifie un circuit existant : reserve au createur du camp\nrouter.put("/:id", async (req: AuthRequest, res) => {\n  const existing = await prisma.campCircuit.findUnique({ where: { id: req.params.id } });\n  if (!existing) return res.status(404).json({ error: "Circuit introuvable." });\n\n  const parsed = circuitSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const data = parsed.data;\n\n  const check = await assertCoach(req.userId!, data.campId);\n  if (!check.ok) return res.status(check.status).json({ error: check.error });\n\n  const circuit = await prisma.campCircuit.update({\n    where: { id: req.params.id },\n    data: {\n      name: data.name,\n      description: data.description ?? null,\n      items: JSON.stringify(data.items),\n      workSeconds: data.workSeconds,\n      restSeconds: data.restSeconds,\n      rounds: data.rounds,\n      roundRestSeconds: data.roundRestSeconds,\n      recurrenceType: data.recurrenceType,\n      daysOfWeek: data.recurrenceType === "WEEKLY" ? JSON.stringify(data.daysOfWeek) : null,\n      intervalDays: data.recurrenceType === "EVERY_N_DAYS" ? data.intervalDays : null,\n    },\n  });\n\n  res.json(circuit);\n});\n\n// Supprime un circuit : reserve au createur du camp\nrouter.delete("/:id", async (req: AuthRequest, res) => {\n  const existing = await prisma.campCircuit.findUnique({ where: { id: req.params.id } });\n  if (!existing) return res.status(404).json({ error: "Circuit introuvable." });\n\n  const check = await assertCoach(req.userId!, existing.campId);\n  if (!check.ok) return res.status(check.status).json({ error: check.error });\n\n  await prisma.campCircuit.delete({ where: { id: req.params.id } });\n  res.status(204).send();\n});\n\nconst logSchema = z.object({ durationSeconds: z.number().min(0) });\n\n// Valide la realisation d\'un circuit de camp pour aujourd\'hui (accessible a tout membre du camp)\nrouter.post("/:id/log", async (req: AuthRequest, res) => {\n  const circuit = await prisma.campCircuit.findUnique({ where: { id: req.params.id } });\n  if (!circuit) return res.status(404).json({ error: "Circuit introuvable." });\n\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId: circuit.campId } },\n  });\n  if (!membership) return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n\n  const parsed = logSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Duree invalide." });\n  }\n\n  const day = toDayStart(new Date());\n  const log = await prisma.campCircuitLog.upsert({\n    where: { userId_campCircuitId_date: { userId: req.userId!, campCircuitId: circuit.id, date: day } },\n    create: {\n      userId: req.userId!,\n      campCircuitId: circuit.id,\n      campId: circuit.campId,\n      date: day,\n      durationSeconds: parsed.data.durationSeconds,\n      completed: true,\n    },\n    update: { durationSeconds: parsed.data.durationSeconds, completed: true },\n  });\n\n  const newBadges = await checkAndAwardBadges(req.userId!);\n  res.status(201).json({ log, newBadges });\n});\n\nexport default router;\n'
FILES['backend/src/routes/chronoSessions.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { checkAndAwardBadges } from "../utils/badges";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nconst sessionSchema = z.object({\n  name: z.string().max(200).optional().nullable(),\n  items: z.array(z.string().min(1)).min(1),\n  workSeconds: z.number().min(1),\n  restSeconds: z.number().min(0),\n  rounds: z.number().min(1),\n  roundRestSeconds: z.number().min(0),\n  totalDurationSeconds: z.number().min(1),\n});\n\n// Enregistre une seance de circuit training "libre" (construite depuis l\'onglet Chrono,\n// independante de tout camp) une fois qu\'elle est terminee.\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = sessionSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const data = parsed.data;\n\n  const session = await prisma.chronoSession.create({\n    data: {\n      userId: req.userId!,\n      name: data.name ?? null,\n      items: JSON.stringify(data.items),\n      workSeconds: data.workSeconds,\n      restSeconds: data.restSeconds,\n      rounds: data.rounds,\n      roundRestSeconds: data.roundRestSeconds,\n      totalDurationSeconds: data.totalDurationSeconds,\n    },\n  });\n\n  const newBadges = await checkAndAwardBadges(req.userId!);\n  res.status(201).json({ session, newBadges });\n});\n\n// Liste les seances chrono libres de l\'utilisateur (les plus recentes en premier)\nrouter.get("/", async (req: AuthRequest, res) => {\n  const sessions = await prisma.chronoSession.findMany({\n    where: { userId: req.userId },\n    orderBy: { completedAt: "desc" },\n    take: 100,\n  });\n  res.json(sessions);\n});\n\nexport default router;\n'
FILES['backend/src/routes/activity.ts'] = 'import { Router } from "express";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Historique complet de l\'activite de l\'utilisateur (exercices individuels, circuits de camp,\n// seances chrono libres), avec quelques statistiques agregees. Sert de "carnet d\'entrainement".\nrouter.get("/", async (req: AuthRequest, res) => {\n  const userId = req.userId!;\n\n  const [exerciseLogs, circuitLogs, chronoSessions] = await Promise.all([\n    prisma.exerciseLog.findMany({\n      where: { userId },\n      include: { exercise: true, camp: { select: { name: true } } },\n      orderBy: { date: "desc" },\n    }),\n    prisma.campCircuitLog.findMany({\n      where: { userId },\n      include: { campCircuit: { select: { name: true } }, camp: { select: { name: true } } },\n      orderBy: { date: "desc" },\n    }),\n    prisma.chronoSession.findMany({\n      where: { userId },\n      orderBy: { completedAt: "desc" },\n    }),\n  ]);\n\n  const items = [\n    ...exerciseLogs.map((l) => ({\n      type: "exercise" as const,\n      date: l.date.toISOString(),\n      exerciseName: l.exercise.name,\n      unit: l.exercise.unit,\n      campName: l.camp.name,\n      setsDone: l.setsDone,\n      valueDone: l.valueDone,\n    })),\n    ...circuitLogs.map((l) => ({\n      type: "circuit" as const,\n      date: l.date.toISOString(),\n      circuitName: l.campCircuit.name,\n      campName: l.camp.name,\n      durationSeconds: l.durationSeconds,\n    })),\n    ...chronoSessions.map((s) => ({\n      type: "chrono" as const,\n      date: s.completedAt.toISOString(),\n      name: s.name,\n      items: JSON.parse(s.items) as string[],\n      totalDurationSeconds: s.totalDurationSeconds,\n      rounds: s.rounds,\n    })),\n  ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());\n\n  // Statistiques agregees\n  const totalSessions = exerciseLogs.length + circuitLogs.length + chronoSessions.length;\n\n  // Temps de pratique : uniquement ce qui est mesurable (exercices en secondes + circuits + chrono libre).\n  // Les exercices en repetitions n\'ont pas de duree intrinseque, ils comptent dans le nombre de seances\n  // mais pas dans le temps total.\n  const exerciseSeconds = exerciseLogs\n    .filter((l) => l.exercise.unit === "SECONDS")\n    .reduce((sum, l) => sum + l.setsDone * l.valueDone, 0);\n  const circuitSeconds = circuitLogs.reduce((sum, l) => sum + l.durationSeconds, 0);\n  const chronoSeconds = chronoSessions.reduce((sum, s) => sum + s.totalDurationSeconds, 0);\n  const totalPracticeSeconds = exerciseSeconds + circuitSeconds + chronoSeconds;\n\n  const exerciseNames = new Set(exerciseLogs.map((l) => l.exercise.name));\n\n  // Record personnel par exercice : la meilleure valeur realisee sur UNE serie (pas le cumul)\n  const bestByExercise = new Map<string, { exerciseName: string; unit: string; best: number }>();\n  for (const l of exerciseLogs) {\n    const current = bestByExercise.get(l.exerciseId);\n    if (!current || l.valueDone > current.best) {\n      bestByExercise.set(l.exerciseId, { exerciseName: l.exercise.name, unit: l.exercise.unit, best: l.valueDone });\n    }\n  }\n\n  res.json({\n    stats: {\n      totalSessions,\n      totalPracticeSeconds,\n      exerciseCount: exerciseNames.size,\n      personalBests: [...bestByExercise.values()],\n    },\n    items,\n  });\n});\n\nexport default router;\n'
FILES['backend/src/routes/today.ts'] = 'import { Router } from "express";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { isDueOnDate, toDayStart } from "../utils/recurrence";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Renvoie, pour aujourd\'hui, tous les exercices et circuits dus (tous camps dont l\'utilisateur\n// est membre) selon la consigne definie par le createur de chaque camp, avec l\'info si deja fait.\nrouter.get("/", async (req: AuthRequest, res) => {\n  const today = toDayStart(new Date());\n\n  const memberships = await prisma.campMembership.findMany({\n    where: { userId: req.userId },\n    include: {\n      camp: {\n        include: { exercises: { include: { exercise: true } }, circuits: true },\n      },\n    },\n  });\n\n  const campExercises = memberships.flatMap((m) =>\n    m.camp.exercises.map((ce) => ({ ...ce, camp: m.camp }))\n  );\n  const campCircuits = memberships.flatMap((m) => m.camp.circuits.map((cc) => ({ ...cc, camp: m.camp })));\n\n  // On ne propose que ce dont le camp est en cours (entre sa date de debut et de fin, si definies)\n  function withinCampDates(camp: { startDate: Date | null; endDate: Date | null }) {\n    if (camp.startDate && today.getTime() < toDayStart(camp.startDate).getTime()) return false;\n    if (camp.endDate && today.getTime() > toDayStart(camp.endDate).getTime()) return false;\n    return true;\n  }\n\n  const dueExercises = campExercises.filter((ce) => withinCampDates(ce.camp) && isDueOnDate(ce, today));\n  const dueCircuits = campCircuits.filter((cc) => withinCampDates(cc.camp) && isDueOnDate(cc, today));\n\n  const [logsToday, circuitLogsToday] = await Promise.all([\n    prisma.exerciseLog.findMany({ where: { userId: req.userId, date: today } }),\n    prisma.campCircuitLog.findMany({ where: { userId: req.userId, date: today } }),\n  ]);\n  const logByExercise = new Map(logsToday.map((l) => [`${l.campId}:${l.exerciseId}`, l]));\n  const logByCircuit = new Map(circuitLogsToday.map((l) => [l.campCircuitId, l]));\n\n  // Pour les exercices en mode "MAX", on va chercher le record personnel precedent a titre de reference\n  const maxExercises = dueExercises.filter((ce) => ce.targetMode === "MAX");\n  const bestByExercise = new Map<string, number>();\n  for (const ce of maxExercises) {\n    const best = await prisma.exerciseLog.findFirst({\n      where: { userId: req.userId, campId: ce.campId, exerciseId: ce.exerciseId },\n      orderBy: { valueDone: "desc" },\n    });\n    if (best) bestByExercise.set(`${ce.campId}:${ce.exerciseId}`, best.valueDone);\n  }\n\n  const exerciseItems = dueExercises.map((ce) => {\n    const key = `${ce.campId}:${ce.exerciseId}`;\n    const log = logByExercise.get(key);\n    return {\n      kind: "exercise" as const,\n      campExerciseId: ce.id,\n      campId: ce.campId,\n      campName: ce.camp.name,\n      exerciseId: ce.exerciseId,\n      exerciseName: ce.exercise.name,\n      description: ce.description,\n      unit: ce.exercise.unit,\n      targetSets: ce.targetSets,\n      targetMode: ce.targetMode,\n      targetValue: ce.targetValue,\n      personalBest: bestByExercise.get(key) ?? null,\n      done: !!log,\n      log: log ? { setsDone: log.setsDone, valueDone: log.valueDone } : null,\n    };\n  });\n\n  const circuitItems = dueCircuits.map((cc) => {\n    const log = logByCircuit.get(cc.id);\n    return {\n      kind: "circuit" as const,\n      campCircuitId: cc.id,\n      campId: cc.campId,\n      campName: cc.camp.name,\n      name: cc.name,\n      description: cc.description,\n      items: JSON.parse(cc.items) as { exerciseId?: string; name: string }[],\n      workSeconds: cc.workSeconds,\n      restSeconds: cc.restSeconds,\n      rounds: cc.rounds,\n      roundRestSeconds: cc.roundRestSeconds,\n      done: !!log,\n    };\n  });\n\n  res.json({ date: today.toISOString().slice(0, 10), items: exerciseItems, circuits: circuitItems });\n});\n\nexport default router;\n'
FILES['backend/src/routes/camps.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { generateCampCode } from "../utils/code";\nimport { isDueOnDate, toDayStart } from "../utils/recurrence";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nconst createCampSchema = z.object({\n  name: z.string().min(1, "Le nom du camp est requis."),\n  description: z.string().max(500).optional().nullable(),\n  exerciseIds: z.array(z.string()).min(1, "Selectionne au moins un exercice."),\n  startDate: z.string().optional().nullable(), // format ISO "YYYY-MM-DD"\n  endDate: z.string().optional().nullable(),\n});\n\n// Cree un camp : choix d\'un ensemble d\'exercices, generation d\'un code d\'invitation.\n// Le createur devient automatiquement membre du camp.\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = createCampSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const { name, description, exerciseIds, startDate, endDate } = parsed.data;\n\n  if (startDate && endDate && new Date(endDate) < new Date(startDate)) {\n    return res.status(400).json({ error: "La date de fin doit etre apres la date de debut." });\n  }\n\n  // On genere un code unique (tres faible probabilite de collision, on retente si besoin)\n  let code = generateCampCode();\n  for (let attempt = 0; attempt < 5; attempt++) {\n    const clash = await prisma.camp.findUnique({ where: { code } });\n    if (!clash) break;\n    code = generateCampCode();\n  }\n\n  const camp = await prisma.camp.create({\n    data: {\n      name,\n      description: description || null,\n      code,\n      createdById: req.userId!,\n      startDate: startDate ? new Date(startDate) : null,\n      endDate: endDate ? new Date(endDate) : null,\n      exercises: { create: exerciseIds.map((exerciseId) => ({ exerciseId })) },\n      members: { create: [{ userId: req.userId! }] },\n    },\n    include: { exercises: { include: { exercise: true } }, members: true },\n  });\n\n  res.status(201).json(camp);\n});\n\nconst joinSchema = z.object({ code: z.string().min(1) });\n\n// Rejoint un camp existant via son code d\'invitation\nrouter.post("/join", async (req: AuthRequest, res) => {\n  const parsed = joinSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Code requis." });\n  }\n  const code = parsed.data.code.trim().toUpperCase();\n\n  const camp = await prisma.camp.findUnique({ where: { code } });\n  if (!camp) {\n    return res.status(404).json({ error: "Aucun camp ne correspond a ce code." });\n  }\n\n  const existing = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId: camp.id } },\n  });\n  if (existing) {\n    return res.status(200).json({ message: "Tu es deja membre de ce camp.", campId: camp.id });\n  }\n\n  await prisma.campMembership.create({ data: { userId: req.userId!, campId: camp.id } });\n  res.status(201).json({ message: `Bienvenue dans le camp "${camp.name}" !`, campId: camp.id });\n});\n\n// Liste les camps dont l\'utilisateur est membre\nrouter.get("/mine", async (req: AuthRequest, res) => {\n  const memberships = await prisma.campMembership.findMany({\n    where: { userId: req.userId },\n    include: {\n      camp: {\n        include: {\n          exercises: { include: { exercise: true } },\n          _count: { select: { members: true } },\n        },\n      },\n    },\n    orderBy: { joinedAt: "desc" },\n  });\n  res.json(memberships.map((m) => m.camp));\n});\n\n// Detail d\'un camp (verifie que l\'utilisateur en est bien membre)\nrouter.get("/:id", async (req: AuthRequest, res) => {\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId: req.params.id } },\n  });\n  if (!membership) {\n    return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n  }\n\n  const camp = await prisma.camp.findUnique({\n    where: { id: req.params.id },\n    include: {\n      exercises: { include: { exercise: true } },\n      circuits: true,\n      members: { include: { user: { select: { id: true, name: true } } } },\n    },\n  });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n  res.json(camp);\n});\n\nconst updateCampSchema = z.object({\n  name: z.string().min(1).optional(),\n  description: z.string().max(500).optional().nullable(),\n});\n\n// Modifie le nom/descriptif d\'un camp : reserve au createur du camp\nrouter.put("/:id", async (req: AuthRequest, res) => {\n  const camp = await prisma.camp.findUnique({ where: { id: req.params.id } });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n  if (camp.createdById !== req.userId) {\n    return res.status(403).json({ error: "Seul le createur du camp peut le modifier." });\n  }\n\n  const parsed = updateCampSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n\n  const updated = await prisma.camp.update({\n    where: { id: req.params.id },\n    data: parsed.data,\n  });\n  res.json(updated);\n});\n\n// Supprime definitivement un camp : reserve au createur du camp.\n// Supprime aussi en cascade les exercices du camp, les adhesions, les logs et les messages associes.\nrouter.delete("/:id", async (req: AuthRequest, res) => {\n  const camp = await prisma.camp.findUnique({ where: { id: req.params.id } });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n  if (camp.createdById !== req.userId) {\n    return res.status(403).json({ error: "Seul le createur du camp peut le supprimer." });\n  }\n\n  await prisma.camp.delete({ where: { id: req.params.id } });\n  res.status(204).send();\n});\n\n// Classement des membres du camp base UNIQUEMENT sur leur regularite personnelle\n// (taux de seances realisees par rapport aux seances dues, et jours consecutifs) --\n// jamais sur les performances (poids, repetitions, etc.).\nrouter.get("/:id/leaderboard", async (req: AuthRequest, res) => {\n  const campId = req.params.id;\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId } },\n  });\n  if (!membership) return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n\n  const camp = await prisma.camp.findUnique({\n    where: { id: campId },\n    include: {\n      exercises: true,\n      members: { include: { user: { select: { id: true, name: true } } } },\n    },\n  });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n\n  const today = toDayStart(new Date());\n  const results = [];\n\n  for (const member of camp.members) {\n    const logs = await prisma.exerciseLog.findMany({\n      where: { userId: member.userId, campId },\n      select: { date: true },\n    });\n    const completedDates = new Set(logs.map((l) => l.date.toISOString().slice(0, 10)));\n\n    let dueCount = 0;\n    let doneCount = 0;\n    for (const ce of camp.exercises) {\n      const effectiveStart = toDayStart(\n        new Date(Math.max(new Date(ce.startDate).getTime(), new Date(member.joinedAt).getTime()))\n      );\n      const cursor = new Date(effectiveStart);\n      while (cursor.getTime() <= today.getTime()) {\n        if (isDueOnDate(ce, cursor)) {\n          dueCount++;\n          if (completedDates.has(cursor.toISOString().slice(0, 10))) doneCount++;\n        }\n        cursor.setUTCDate(cursor.getUTCDate() + 1);\n      }\n    }\n    const regularityRate = dueCount > 0 ? Math.round((doneCount / dueCount) * 100) : 0;\n\n    // Streak propre a ce camp : jours consecutifs (en remontant depuis aujourd\'hui/hier)\n    // avec au moins une seance validee dans ce camp.\n    let streak = 0;\n    const cursor2 = toDayStart(today);\n    if (!completedDates.has(cursor2.toISOString().slice(0, 10))) {\n      cursor2.setUTCDate(cursor2.getUTCDate() - 1);\n    }\n    for (let i = 0; i < 3650; i++) {\n      const key = cursor2.toISOString().slice(0, 10);\n      if (!completedDates.has(key)) break;\n      streak++;\n      cursor2.setUTCDate(cursor2.getUTCDate() - 1);\n    }\n\n    results.push({\n      userId: member.userId,\n      name: member.user.name,\n      regularityRate,\n      streak,\n      dueCount,\n      doneCount,\n    });\n  }\n\n  results.sort((a, b) => b.regularityRate - a.regularityRate || b.streak - a.streak);\n  res.json(results);\n});\n\nexport default router;\n'
FILES['backend/src/index.ts'] = 'import "dotenv/config";\nimport express from "express";\nimport cors from "cors";\n\nimport authRoutes from "./routes/auth";\nimport userRoutes from "./routes/users";\nimport exerciseRoutes from "./routes/exercises";\nimport campRoutes from "./routes/camps";\nimport campExerciseRoutes from "./routes/campExercises";\nimport todayRoutes from "./routes/today";\nimport logRoutes from "./routes/logs";\nimport progressRoutes from "./routes/progress";\nimport pushRoutes from "./routes/push";\nimport badgeRoutes from "./routes/badges";\nimport campMessageRoutes from "./routes/campMessages";\nimport messageRoutes from "./routes/messages";\nimport campCircuitRoutes from "./routes/campCircuits";\nimport chronoSessionRoutes from "./routes/chronoSessions";\nimport activityRoutes from "./routes/activity";\nimport { initPush, scheduleReminders } from "./services/notifications";\n\nconst app = express();\n\napp.use(cors({ origin: process.env.FRONTEND_URL || "*" }));\napp.use(express.json());\n\napp.get("/api/health", (_req, res) => res.json({ status: "ok" }));\n\napp.use("/api/auth", authRoutes);\napp.use("/api/users", userRoutes);\napp.use("/api/exercises", exerciseRoutes);\napp.use("/api/camps", campRoutes);\napp.use("/api/camp-exercises", campExerciseRoutes);\napp.use("/api/today", todayRoutes);\napp.use("/api/logs", logRoutes);\napp.use("/api/progress", progressRoutes);\napp.use("/api/push", pushRoutes);\napp.use("/api/badges", badgeRoutes);\napp.use("/api/camps", campMessageRoutes);\napp.use("/api/messages", messageRoutes);\napp.use("/api/camp-circuits", campCircuitRoutes);\napp.use("/api/chrono-sessions", chronoSessionRoutes);\napp.use("/api/activity", activityRoutes);\n\n// Gestion d\'erreur generique (evite qu\'une exception fasse planter le process)\napp.use((err: any, _req: express.Request, res: express.Response, _next: express.NextFunction) => {\n  console.error(err);\n  res.status(500).json({ error: "Erreur interne du serveur." });\n});\n\nconst port = Number(process.env.PORT || 4000);\n\ninitPush();\nscheduleReminders();\n\napp.listen(port, () => {\n  console.log(`API demarree sur http://localhost:${port}`);\n});\n'
FILES['frontend/src/components/CircuitRunner.tsx'] = 'import { useEffect, useRef, useState } from "react";\n\nexport interface CircuitRunnerItem {\n  name: string;\n}\n\ninterface Props {\n  items: CircuitRunnerItem[];\n  workSeconds: number;\n  restSeconds: number;\n  rounds: number;\n  roundRestSeconds: number;\n  onComplete: (totalDurationSeconds: number) => void;\n  onCancel: () => void;\n}\n\ntype Phase =\n  | { type: "work"; exerciseName: string; duration: number; round: number; totalRounds: number; index: number; total: number }\n  | { type: "rest"; duration: number; round: number; totalRounds: number; nextExerciseName: string }\n  | { type: "roundRest"; duration: number; round: number; totalRounds: number };\n\nfunction beep(freq: number, duration = 180) {\n  try {\n    const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;\n    const ctx = new AudioCtx();\n    const osc = ctx.createOscillator();\n    const gain = ctx.createGain();\n    osc.frequency.value = freq;\n    osc.connect(gain);\n    gain.connect(ctx.destination);\n    gain.gain.setValueAtTime(0.2, ctx.currentTime);\n    osc.start();\n    osc.stop(ctx.currentTime + duration / 1000);\n    osc.onended = () => ctx.close();\n  } catch {\n    // navigateur sans Web Audio : tant pis, pas de son\n  }\n}\n\nfunction buildPhases(\n  items: CircuitRunnerItem[],\n  workSeconds: number,\n  restSeconds: number,\n  rounds: number,\n  roundRestSeconds: number\n): Phase[] {\n  const phases: Phase[] = [];\n  for (let round = 1; round <= rounds; round++) {\n    items.forEach((item, index) => {\n      phases.push({\n        type: "work",\n        exerciseName: item.name,\n        duration: workSeconds,\n        round,\n        totalRounds: rounds,\n        index: index + 1,\n        total: items.length,\n      });\n      const isLastExerciseOfRound = index === items.length - 1;\n      if (!isLastExerciseOfRound && restSeconds > 0) {\n        phases.push({\n          type: "rest",\n          duration: restSeconds,\n          round,\n          totalRounds: rounds,\n          nextExerciseName: items[index + 1].name,\n        });\n      }\n    });\n    if (round < rounds && roundRestSeconds > 0) {\n      phases.push({ type: "roundRest", duration: roundRestSeconds, round, totalRounds: rounds });\n    }\n  }\n  return phases;\n}\n\n// Composant plein ecran qui deroule un circuit (travail/repos/tours) avec bips sonores aux transitions.\nexport default function CircuitRunner({ items, workSeconds, restSeconds, rounds, roundRestSeconds, onComplete, onCancel }: Props) {\n  const [phases] = useState<Phase[]>(() => buildPhases(items, workSeconds, restSeconds, rounds, roundRestSeconds));\n  const [phaseIndex, setPhaseIndex] = useState(0);\n  const [remaining, setRemaining] = useState(phases[0]?.duration ?? 0);\n  const [running, setRunning] = useState(true);\n  const [finished, setFinished] = useState(false);\n  const elapsedRef = useRef(0);\n  const intervalRef = useRef<number | null>(null);\n\n  useEffect(() => {\n    beep(880);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  function skipPhase() {\n    if (phaseIndex + 1 >= phases.length) {\n      setFinished(true);\n      setRunning(false);\n      beep(660, 400);\n      return;\n    }\n    setPhaseIndex((i) => i + 1);\n    setRemaining(phases[phaseIndex + 1].duration);\n    beep(phases[phaseIndex + 1].type === "work" ? 880 : 440);\n  }\n\n  useEffect(() => {\n    if (!running) return;\n    intervalRef.current = window.setInterval(() => {\n      elapsedRef.current += 1;\n      setRemaining((r) => {\n        if (r <= 1) {\n          if (phaseIndex + 1 >= phases.length) {\n            setFinished(true);\n            setRunning(false);\n            beep(660, 400);\n            return 0;\n          }\n          setPhaseIndex((i) => i + 1);\n          beep(phases[phaseIndex + 1].type === "work" ? 880 : 440);\n          return phases[phaseIndex + 1].duration;\n        }\n        return r - 1;\n      });\n    }, 1000);\n    return () => {\n      if (intervalRef.current) window.clearInterval(intervalRef.current);\n    };\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [running, phaseIndex]);\n\n  const currentPhase = phases[phaseIndex];\n\n  if (finished) {\n    return (\n      <div className="max-w-md mx-auto text-center pt-6">\n        <h2 className="font-display text-3xl uppercase tracking-wide mb-4">Circuit termine ! 🎉</h2>\n        <p className="text-muted text-sm mb-6">Bien joue, seance complete.</p>\n        <button\n          onClick={() => onComplete(elapsedRef.current)}\n          className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-5 py-2"\n        >\n          Valider et continuer\n        </button>\n      </div>\n    );\n  }\n\n  if (!currentPhase) return null;\n\n  const phaseColor = currentPhase.type === "work" ? "text-accent border-accent" : "text-success border-success";\n\n  return (\n    <div className="max-w-md mx-auto text-center pt-6">\n      <p className="text-muted text-sm mb-1">\n        Tour {currentPhase.round} / {currentPhase.totalRounds}\n        {currentPhase.type === "work" && ` · Exercice ${currentPhase.index}/${currentPhase.total}`}\n      </p>\n      <div className={`border-4 rounded-full w-56 h-56 mx-auto flex flex-col items-center justify-center my-6 ${phaseColor}`}>\n        <p className="font-display text-6xl">{remaining}</p>\n        <p className="text-xs text-muted uppercase tracking-wide">secondes</p>\n      </div>\n      <h2 className="font-display text-2xl uppercase tracking-wide mb-1">\n        {currentPhase.type === "work"\n          ? currentPhase.exerciseName\n          : currentPhase.type === "rest"\n          ? `Repos — ensuite : ${currentPhase.nextExerciseName}`\n          : "Repos entre les tours"}\n      </h2>\n\n      <div className="flex justify-center gap-3 mt-6">\n        <button\n          onClick={() => setRunning((r) => !r)}\n          className="bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-4 py-2 text-sm"\n        >\n          {running ? "Pause" : "Reprendre"}\n        </button>\n        <button\n          onClick={skipPhase}\n          className="bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-4 py-2 text-sm"\n        >\n          Passer\n        </button>\n        <button onClick={onCancel} className="text-muted hover:text-accent text-sm px-3 py-2">\n          Arreter\n        </button>\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/components/CampCircuitForm.tsx'] = 'import { useMemo, useState } from "react";\nimport { api, ApiError } from "../api/client";\n\ninterface CatalogExercise {\n  id: string;\n  name: string;\n}\n\ninterface CircuitItem {\n  key: string;\n  name: string;\n}\n\nexport interface CampCircuitData {\n  id: string;\n  name: string;\n  description: string | null;\n  items: string; // JSON\n  workSeconds: number;\n  restSeconds: number;\n  rounds: number;\n  roundRestSeconds: number;\n  recurrenceType: "DAILY" | "WEEKLY" | "EVERY_N_DAYS";\n  daysOfWeek: string | null;\n  intervalDays: number | null;\n}\n\ninterface Props {\n  campId: string;\n  catalog: CatalogExercise[];\n  existing?: CampCircuitData;\n  onSaved: () => void;\n  onCancel: () => void;\n}\n\nconst WEEKDAYS = [\n  { value: 1, label: "Lun" },\n  { value: 2, label: "Mar" },\n  { value: 3, label: "Mer" },\n  { value: 4, label: "Jeu" },\n  { value: 5, label: "Ven" },\n  { value: 6, label: "Sam" },\n  { value: 0, label: "Dim" },\n];\n\nexport default function CampCircuitForm({ campId, catalog, existing, onSaved, onCancel }: Props) {\n  const [name, setName] = useState(existing?.name ?? "");\n  const [description, setDescription] = useState(existing?.description ?? "");\n  const [items, setItems] = useState<CircuitItem[]>(() => {\n    if (!existing) return [];\n    const parsed = JSON.parse(existing.items) as { name: string }[];\n    return parsed.map((p, i) => ({ key: `${p.name}-${i}`, name: p.name }));\n  });\n  const [search, setSearch] = useState("");\n  const [customName, setCustomName] = useState("");\n\n  const [workSeconds, setWorkSeconds] = useState(existing?.workSeconds ?? 40);\n  const [restSeconds, setRestSeconds] = useState(existing?.restSeconds ?? 20);\n  const [rounds, setRounds] = useState(existing?.rounds ?? 3);\n  const [roundRestSeconds, setRoundRestSeconds] = useState(existing?.roundRestSeconds ?? 60);\n  const [recurrenceType, setRecurrenceType] = useState<"DAILY" | "WEEKLY" | "EVERY_N_DAYS">(\n    existing?.recurrenceType ?? "DAILY"\n  );\n  const [daysOfWeek, setDaysOfWeek] = useState<number[]>(\n    existing?.daysOfWeek ? JSON.parse(existing.daysOfWeek) : [1, 3, 5]\n  );\n  const [intervalDays, setIntervalDays] = useState(existing?.intervalDays ?? 2);\n\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n\n  const filteredCatalog = useMemo(\n    () => catalog.filter((e) => e.name.toLowerCase().includes(search.toLowerCase())),\n    [catalog, search]\n  );\n\n  function addItem(name: string) {\n    setItems((prev) => [...prev, { key: `${name}-${Date.now()}-${Math.random()}`, name }]);\n  }\n\n  function removeItem(key: string) {\n    setItems((prev) => prev.filter((i) => i.key !== key));\n  }\n\n  function moveItem(key: string, direction: -1 | 1) {\n    setItems((prev) => {\n      const index = prev.findIndex((i) => i.key === key);\n      const newIndex = index + direction;\n      if (newIndex < 0 || newIndex >= prev.length) return prev;\n      const copy = [...prev];\n      [copy[index], copy[newIndex]] = [copy[newIndex], copy[index]];\n      return copy;\n    });\n  }\n\n  function toggleDay(day: number) {\n    setDaysOfWeek((prev) => (prev.includes(day) ? prev.filter((d) => d !== day) : [...prev, day].sort()));\n  }\n\n  async function save() {\n    setError(null);\n    if (!name.trim()) {\n      setError("Le nom du circuit est requis.");\n      return;\n    }\n    if (items.length === 0) {\n      setError("Ajoute au moins un exercice au circuit.");\n      return;\n    }\n    if (recurrenceType === "WEEKLY" && daysOfWeek.length === 0) {\n      setError("Choisis au moins un jour de la semaine.");\n      return;\n    }\n    setBusy(true);\n    try {\n      const payload: Record<string, unknown> = {\n        campId,\n        name: name.trim(),\n        description: description.trim() || null,\n        items: items.map((i) => ({ name: i.name })),\n        workSeconds,\n        restSeconds,\n        rounds,\n        roundRestSeconds,\n        recurrenceType,\n      };\n      if (recurrenceType === "WEEKLY") payload.daysOfWeek = daysOfWeek;\n      if (recurrenceType === "EVERY_N_DAYS") payload.intervalDays = intervalDays;\n\n      if (existing) {\n        await api.put(`/camp-circuits/${existing.id}`, payload);\n      } else {\n        await api.post("/camp-circuits", payload);\n      }\n      onSaved();\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Impossible d\'enregistrer ce circuit.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <div className="bg-surface2 border border-border rounded-lg p-4 space-y-3">\n      <h3 className="font-display uppercase tracking-wide text-sm">\n        {existing ? "Modifier le circuit" : "Nouveau circuit"}\n      </h3>\n\n      <div>\n        <label className="block text-xs text-muted mb-1">Nom du circuit</label>\n        <input\n          value={name}\n          onChange={(e) => setName(e.target.value)}\n          placeholder="Ex : Circuit explosivite"\n          className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm"\n        />\n      </div>\n\n      <div>\n        <label className="block text-xs text-muted mb-1">Description (optionnel)</label>\n        <textarea\n          value={description}\n          onChange={(e) => setDescription(e.target.value)}\n          rows={2}\n          className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm resize-none"\n        />\n      </div>\n\n      <div>\n        <label className="block text-xs text-muted mb-1">Exercices du circuit</label>\n        <input\n          placeholder="Rechercher un exercice..."\n          value={search}\n          onChange={(e) => setSearch(e.target.value)}\n          className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm mb-1.5"\n        />\n        <div className="grid grid-cols-2 gap-1 max-h-28 overflow-y-auto mb-2">\n          {filteredCatalog.map((exo) => (\n            <button\n              key={exo.id}\n              type="button"\n              onClick={() => addItem(exo.name)}\n              className="text-left text-xs bg-surface hover:bg-border transition-colors border border-border rounded px-2 py-1"\n            >\n              + {exo.name}\n            </button>\n          ))}\n        </div>\n        <div className="flex gap-2 mb-2">\n          <input\n            value={customName}\n            onChange={(e) => setCustomName(e.target.value)}\n            placeholder="Nouvel exercice..."\n            className="flex-1 bg-surface border border-border rounded-md px-2 py-1.5 text-xs"\n          />\n          <button\n            type="button"\n            onClick={() => {\n              if (customName.trim()) addItem(customName.trim());\n              setCustomName("");\n            }}\n            className="bg-accent text-bg font-semibold rounded-md px-3 py-1.5 text-xs"\n          >\n            Ajouter\n          </button>\n        </div>\n\n        <div className="space-y-1">\n          {items.map((item, index) => (\n            <div key={item.key} className="flex items-center justify-between bg-surface border border-border rounded px-2 py-1 text-xs">\n              <span>{index + 1}. {item.name}</span>\n              <div className="flex gap-1">\n                <button onClick={() => moveItem(item.key, -1)} className="text-muted hover:text-text px-1">↑</button>\n                <button onClick={() => moveItem(item.key, 1)} className="text-muted hover:text-text px-1">↓</button>\n                <button onClick={() => removeItem(item.key)} className="text-muted hover:text-accent px-1">✕</button>\n              </div>\n            </div>\n          ))}\n        </div>\n      </div>\n\n      <div className="grid grid-cols-2 gap-3">\n        <div>\n          <label className="block text-xs text-muted mb-1">Travail (sec)</label>\n          <input type="number" min={5} value={workSeconds} onChange={(e) => setWorkSeconds(Number(e.target.value))} className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm" />\n        </div>\n        <div>\n          <label className="block text-xs text-muted mb-1">Repos entre exercices (sec)</label>\n          <input type="number" min={0} value={restSeconds} onChange={(e) => setRestSeconds(Number(e.target.value))} className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm" />\n        </div>\n        <div>\n          <label className="block text-xs text-muted mb-1">Nombre de tours</label>\n          <input type="number" min={1} value={rounds} onChange={(e) => setRounds(Number(e.target.value))} className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm" />\n        </div>\n        <div>\n          <label className="block text-xs text-muted mb-1">Repos entre tours (sec)</label>\n          <input type="number" min={0} value={roundRestSeconds} onChange={(e) => setRoundRestSeconds(Number(e.target.value))} className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm" />\n        </div>\n      </div>\n\n      <div>\n        <label className="block text-xs text-muted mb-1">Frequence</label>\n        <select\n          value={recurrenceType}\n          onChange={(e) => setRecurrenceType(e.target.value as any)}\n          className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm mb-2"\n        >\n          <option value="DAILY">Tous les jours</option>\n          <option value="WEEKLY">Certains jours de la semaine</option>\n          <option value="EVERY_N_DAYS">Tous les X jours</option>\n        </select>\n        {recurrenceType === "WEEKLY" && (\n          <div className="flex flex-wrap gap-1.5">\n            {WEEKDAYS.map((d) => (\n              <button\n                type="button"\n                key={d.value}\n                onClick={() => toggleDay(d.value)}\n                className={`px-2.5 py-1 rounded text-xs border ${\n                  daysOfWeek.includes(d.value) ? "bg-accent/20 border-accent text-text" : "bg-surface border-border text-muted"\n                }`}\n              >\n                {d.label}\n              </button>\n            ))}\n          </div>\n        )}\n        {recurrenceType === "EVERY_N_DAYS" && (\n          <div className="flex items-center gap-2 text-sm">\n            <span className="text-muted">Tous les</span>\n            <input type="number" min={1} value={intervalDays} onChange={(e) => setIntervalDays(Number(e.target.value))} className="w-16 bg-surface border border-border rounded-md px-2 py-1" />\n            <span className="text-muted">jours</span>\n          </div>\n        )}\n      </div>\n\n      {error && <p className="text-sm text-accent">{error}</p>}\n\n      <div className="flex gap-2">\n        <button\n          onClick={save}\n          disabled={busy}\n          className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-4 py-1.5 text-sm disabled:opacity-60"\n        >\n          {busy ? "Enregistrement..." : "Enregistrer"}\n        </button>\n        <button onClick={onCancel} className="text-muted hover:text-text text-sm px-2">\n          Annuler\n        </button>\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Chrono.tsx'] = 'import { useEffect, useMemo, useRef, useState } from "react";\nimport { api } from "../api/client";\nimport CircuitRunner from "../components/CircuitRunner";\n\ninterface CatalogExercise {\n  id: string;\n  name: string;\n  unit: "REPS" | "SECONDS";\n}\n\ninterface CircuitItem {\n  key: string;\n  name: string;\n}\n\ninterface NewBadge {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n}\n\nexport default function Chrono() {\n  const [mode, setMode] = useState<"circuit" | "simple">("circuit");\n\n  const [catalog, setCatalog] = useState<CatalogExercise[]>([]);\n  const [search, setSearch] = useState("");\n  const [items, setItems] = useState<CircuitItem[]>([]);\n  const [customName, setCustomName] = useState("");\n\n  const [workSeconds, setWorkSeconds] = useState(40);\n  const [restSeconds, setRestSeconds] = useState(20);\n  const [rounds, setRounds] = useState(3);\n  const [roundRestSeconds, setRoundRestSeconds] = useState(60);\n\n  const [isRunningCircuit, setIsRunningCircuit] = useState(false);\n  const [celebrating, setCelebrating] = useState<NewBadge[]>([]);\n\n  useEffect(() => {\n    api.get<CatalogExercise[]>("/exercises").then(setCatalog);\n  }, []);\n\n  const filteredCatalog = useMemo(\n    () => catalog.filter((e) => e.name.toLowerCase().includes(search.toLowerCase())),\n    [catalog, search]\n  );\n\n  function addItem(name: string) {\n    setItems((prev) => [...prev, { key: `${name}-${Date.now()}-${Math.random()}`, name }]);\n  }\n\n  async function addCustom() {\n    if (!customName.trim()) return;\n    try {\n      const created = await api.post<CatalogExercise>("/exercises", { name: customName.trim(), unit: "REPS" });\n      setCatalog((prev) => [...prev, created]);\n      addItem(created.name);\n    } catch {\n      addItem(customName.trim());\n    }\n    setCustomName("");\n  }\n\n  function removeItem(key: string) {\n    setItems((prev) => prev.filter((i) => i.key !== key));\n  }\n\n  function moveItem(key: string, direction: -1 | 1) {\n    setItems((prev) => {\n      const index = prev.findIndex((i) => i.key === key);\n      const newIndex = index + direction;\n      if (newIndex < 0 || newIndex >= prev.length) return prev;\n      const copy = [...prev];\n      [copy[index], copy[newIndex]] = [copy[newIndex], copy[index]];\n      return copy;\n    });\n  }\n\n  async function onCircuitComplete(totalDurationSeconds: number) {\n    setIsRunningCircuit(false);\n    try {\n      const res = await api.post<{ newBadges: NewBadge[] }>("/chrono-sessions", {\n        items: items.map((i) => i.name),\n        workSeconds,\n        restSeconds,\n        rounds,\n        roundRestSeconds,\n        totalDurationSeconds,\n      });\n      if (res.newBadges?.length) setCelebrating(res.newBadges);\n    } catch {\n      // meme si l\'enregistrement echoue (ex: hors ligne), on ne bloque pas l\'utilisateur\n    }\n  }\n\n  if (isRunningCircuit) {\n    return (\n      <div className="max-w-md mx-auto">\n        <CircuitRunner\n          items={items.map((i) => ({ name: i.name }))}\n          workSeconds={workSeconds}\n          restSeconds={restSeconds}\n          rounds={rounds}\n          roundRestSeconds={roundRestSeconds}\n          onComplete={onCircuitComplete}\n          onCancel={() => setIsRunningCircuit(false)}\n        />\n      </div>\n    );\n  }\n\n  return (\n    <div className="max-w-2xl">\n      {celebrating.length > 0 && (\n        <div className="bg-accent/10 border border-accent rounded-xl p-4 mb-5">\n          {celebrating.map((b) => (\n            <p key={b.key} className="text-sm">\n              <span className="text-xl mr-2">{b.emoji}</span>\n              Nouveau badge : <span className="font-semibold">{b.name}</span> — {b.description}\n            </p>\n          ))}\n          <button onClick={() => setCelebrating([])} className="text-xs text-muted hover:text-text mt-2">\n            Fermer\n          </button>\n        </div>\n      )}\n\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Chronometre</h1>\n      <p className="text-muted text-sm mb-4">\n        Construis ta propre seance en circuit training, ou lance simplement un chrono.\n      </p>\n\n      <div className="flex gap-1.5 mb-6">\n        <button\n          onClick={() => setMode("circuit")}\n          className={`px-3 py-1.5 rounded text-sm border ${\n            mode === "circuit" ? "bg-accent/20 border-accent text-text" : "bg-surface border-border text-muted"\n          }`}\n        >\n          Circuit training\n        </button>\n        <button\n          onClick={() => setMode("simple")}\n          className={`px-3 py-1.5 rounded text-sm border ${\n            mode === "simple" ? "bg-accent/20 border-accent text-text" : "bg-surface border-border text-muted"\n          }`}\n        >\n          Chrono simple\n        </button>\n      </div>\n\n      {mode === "simple" ? (\n        <SimpleTimer />\n      ) : (\n        <div className="grid md:grid-cols-2 gap-6">\n          <div>\n            <h2 className="font-display uppercase tracking-wide text-sm mb-2">1. Choisis tes exercices</h2>\n            <input\n              placeholder="Rechercher un exercice..."\n              value={search}\n              onChange={(e) => setSearch(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2 mb-2 text-sm"\n            />\n            <div className="grid grid-cols-2 gap-1.5 max-h-40 overflow-y-auto mb-2">\n              {filteredCatalog.map((exo) => (\n                <button\n                  key={exo.id}\n                  type="button"\n                  onClick={() => addItem(exo.name)}\n                  className="text-left text-sm bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-2 py-1.5"\n                >\n                  + {exo.name}\n                </button>\n              ))}\n            </div>\n            <div className="flex gap-2">\n              <input\n                value={customName}\n                onChange={(e) => setCustomName(e.target.value)}\n                placeholder="Nouvel exercice..."\n                className="flex-1 bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n              />\n              <button\n                type="button"\n                onClick={addCustom}\n                className="bg-accent text-bg font-semibold rounded-md px-3 py-1.5 text-sm"\n              >\n                Ajouter\n              </button>\n            </div>\n\n            <h3 className="font-display uppercase tracking-wide text-xs mt-4 mb-2 text-muted">\n              Circuit ({items.length} exercice{items.length > 1 ? "s" : ""})\n            </h3>\n            <div className="space-y-1.5">\n              {items.length === 0 && <p className="text-muted text-sm italic">Aucun exercice ajoute pour l\'instant.</p>}\n              {items.map((item, index) => (\n                <div\n                  key={item.key}\n                  className="flex items-center justify-between bg-surface border border-border rounded-md px-3 py-1.5 text-sm"\n                >\n                  <span>\n                    {index + 1}. {item.name}\n                  </span>\n                  <div className="flex gap-1 items-center">\n                    <button onClick={() => moveItem(item.key, -1)} className="text-muted hover:text-text px-1">\n                      ↑\n                    </button>\n                    <button onClick={() => moveItem(item.key, 1)} className="text-muted hover:text-text px-1">\n                      ↓\n                    </button>\n                    <button onClick={() => removeItem(item.key)} className="text-muted hover:text-accent px-1">\n                      ✕\n                    </button>\n                  </div>\n                </div>\n              ))}\n            </div>\n          </div>\n\n          <div>\n            <h2 className="font-display uppercase tracking-wide text-sm mb-2">2. Reglages du circuit</h2>\n            <div className="bg-surface border border-border rounded-lg p-4 space-y-3">\n              <div>\n                <label className="block text-xs text-muted mb-1">Temps de travail (secondes)</label>\n                <input\n                  type="number"\n                  min={5}\n                  value={workSeconds}\n                  onChange={(e) => setWorkSeconds(Number(e.target.value))}\n                  className="w-full bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n                />\n              </div>\n              <div>\n                <label className="block text-xs text-muted mb-1">Temps de repos entre exercices (secondes)</label>\n                <input\n                  type="number"\n                  min={0}\n                  value={restSeconds}\n                  onChange={(e) => setRestSeconds(Number(e.target.value))}\n                  className="w-full bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n                />\n              </div>\n              <div>\n                <label className="block text-xs text-muted mb-1">Nombre de tours</label>\n                <input\n                  type="number"\n                  min={1}\n                  value={rounds}\n                  onChange={(e) => setRounds(Number(e.target.value))}\n                  className="w-full bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n                />\n              </div>\n              <div>\n                <label className="block text-xs text-muted mb-1">Repos entre chaque tour (secondes)</label>\n                <input\n                  type="number"\n                  min={0}\n                  value={roundRestSeconds}\n                  onChange={(e) => setRoundRestSeconds(Number(e.target.value))}\n                  className="w-full bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n                />\n              </div>\n            </div>\n\n            <button\n              onClick={() => setIsRunningCircuit(true)}\n              disabled={items.length === 0}\n              className="w-full mt-4 bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md py-2.5 disabled:opacity-50"\n            >\n              Lancer le circuit\n            </button>\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n\n// Chrono simple : un minuteur (compte a rebours) ou chronometre (compte en avant si duree = 0),\n// pour un usage ponctuel sans construire tout un circuit.\nfunction SimpleTimer() {\n  const [inputMinutes, setInputMinutes] = useState(1);\n  const [inputSeconds, setInputSeconds] = useState(0);\n  const [remaining, setRemaining] = useState(60);\n  const [running, setRunning] = useState(false);\n  const [countUp, setCountUp] = useState(false);\n  const intervalRef = useRef<number | null>(null);\n\n  function applySettings() {\n    const total = inputMinutes * 60 + inputSeconds;\n    setCountUp(total === 0);\n    setRemaining(total === 0 ? 0 : total);\n    setRunning(false);\n  }\n\n  useEffect(() => {\n    if (!running) return;\n    intervalRef.current = window.setInterval(() => {\n      setRemaining((r) => {\n        if (countUp) return r + 1;\n        if (r <= 1) {\n          setRunning(false);\n          try {\n            const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;\n            const ctx = new AudioCtx();\n            const osc = ctx.createOscillator();\n            osc.frequency.value = 660;\n            osc.connect(ctx.destination);\n            osc.start();\n            osc.stop(ctx.currentTime + 0.4);\n            osc.onended = () => ctx.close();\n          } catch {\n            /* pas grave si pas de son */\n          }\n          return 0;\n        }\n        return r - 1;\n      });\n    }, 1000);\n    return () => {\n      if (intervalRef.current) window.clearInterval(intervalRef.current);\n    };\n  }, [running, countUp]);\n\n  const mm = Math.floor(remaining / 60);\n  const ss = remaining % 60;\n\n  return (\n    <div className="max-w-sm mx-auto text-center">\n      <div className="border-4 border-accent rounded-full w-56 h-56 mx-auto flex flex-col items-center justify-center my-6">\n        <p className="font-display text-6xl">\n          {mm}:{ss.toString().padStart(2, "0")}\n        </p>\n      </div>\n\n      <div className="flex justify-center gap-3 mb-6">\n        <button\n          onClick={() => setRunning((r) => !r)}\n          className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-5 py-2"\n        >\n          {running ? "Pause" : "Demarrer"}\n        </button>\n        <button\n          onClick={applySettings}\n          className="bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-4 py-2 text-sm"\n        >\n          Reinitialiser\n        </button>\n      </div>\n\n      <div className="bg-surface border border-border rounded-lg p-4">\n        <p className="text-xs text-muted mb-2">\n          Regle une duree pour un compte a rebours, ou laisse 0:00 pour un chronometre qui compte en avant.\n        </p>\n        <div className="flex items-center justify-center gap-2">\n          <input\n            type="number"\n            min={0}\n            value={inputMinutes}\n            onChange={(e) => setInputMinutes(Number(e.target.value))}\n            className="w-16 bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm text-center"\n          />\n          <span className="text-muted text-sm">min</span>\n          <input\n            type="number"\n            min={0}\n            max={59}\n            value={inputSeconds}\n            onChange={(e) => setInputSeconds(Number(e.target.value))}\n            className="w-16 bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm text-center"\n          />\n          <span className="text-muted text-sm">sec</span>\n          <button\n            onClick={applySettings}\n            className="bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-1.5 text-sm"\n          >\n            Appliquer\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Today.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link } from "react-router-dom";\nimport { api } from "../api/client";\nimport DurationInput from "../components/DurationInput";\nimport CircuitRunner from "../components/CircuitRunner";\nimport { secondsToMMSS } from "../lib/duration";\n\ninterface TodayExerciseItem {\n  kind: "exercise";\n  campExerciseId: string;\n  campId: string;\n  campName: string;\n  exerciseId: string;\n  exerciseName: string;\n  description: string | null;\n  unit: "REPS" | "SECONDS";\n  targetSets: number;\n  targetMode: "FIXED" | "MAX";\n  targetValue: number | null;\n  personalBest: number | null;\n  done: boolean;\n  log: { setsDone: number; valueDone: number } | null;\n}\n\ninterface TodayCircuitItem {\n  kind: "circuit";\n  campCircuitId: string;\n  campId: string;\n  campName: string;\n  name: string;\n  description: string | null;\n  items: { exerciseId?: string; name: string }[];\n  workSeconds: number;\n  restSeconds: number;\n  rounds: number;\n  roundRestSeconds: number;\n  done: boolean;\n}\n\ninterface NewBadge {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n}\n\n// Repos par defaut entre chaque serie lors d\'un chrono rapide lance sur un seul exercice\nconst QUICK_CHRONO_REST_SECONDS = 15;\n\nexport default function Today() {\n  const [items, setItems] = useState<TodayExerciseItem[] | null>(null);\n  const [circuits, setCircuits] = useState<TodayCircuitItem[]>([]);\n  const [editingId, setEditingId] = useState<string | null>(null);\n  const [sets, setSets] = useState(0);\n  const [value, setValue] = useState(0);\n  const [celebrating, setCelebrating] = useState<NewBadge[]>([]);\n  const [runner, setRunner] = useState<\n    | { type: "exercise"; item: TodayExerciseItem }\n    | { type: "circuit"; item: TodayCircuitItem }\n    | null\n  >(null);\n\n  function load() {\n    api\n      .get<{ date: string; items: TodayExerciseItem[]; circuits: TodayCircuitItem[] }>("/today")\n      .then((res) => {\n        setItems(res.items);\n        setCircuits(res.circuits);\n      });\n  }\n  useEffect(load, []);\n\n  function startEditing(item: TodayExerciseItem) {\n    setEditingId(item.campExerciseId);\n    setSets(item.log?.setsDone ?? item.targetSets);\n    setValue(item.log?.valueDone ?? item.targetValue ?? item.personalBest ?? 0);\n  }\n\n  async function confirm(item: TodayExerciseItem) {\n    const res = await api.post<{ newBadges: NewBadge[] }>("/logs", {\n      campId: item.campId,\n      exerciseId: item.exerciseId,\n      setsDone: sets,\n      valueDone: value,\n    });\n    setEditingId(null);\n    load();\n    if (res.newBadges?.length) setCelebrating(res.newBadges);\n  }\n\n  async function undo(item: TodayExerciseItem) {\n    await api.del(`/logs?campId=${item.campId}&exerciseId=${item.exerciseId}`);\n    load();\n  }\n\n  async function onExerciseChronoComplete(item: TodayExerciseItem) {\n    const res = await api.post<{ newBadges: NewBadge[] }>("/logs", {\n      campId: item.campId,\n      exerciseId: item.exerciseId,\n      setsDone: item.targetSets,\n      valueDone: item.targetValue ?? 0,\n    });\n    setRunner(null);\n    load();\n    if (res.newBadges?.length) setCelebrating(res.newBadges);\n  }\n\n  async function onCircuitComplete(item: TodayCircuitItem, totalDurationSeconds: number) {\n    const res = await api.post<{ newBadges: NewBadge[] }>(`/camp-circuits/${item.campCircuitId}/log`, {\n      durationSeconds: totalDurationSeconds,\n    });\n    setRunner(null);\n    load();\n    if (res.newBadges?.length) setCelebrating(res.newBadges);\n  }\n\n  if (runner?.type === "exercise") {\n    const item = runner.item;\n    return (\n      <div className="max-w-md mx-auto">\n        <CircuitRunner\n          items={[{ name: item.exerciseName }]}\n          workSeconds={item.targetValue ?? 30}\n          restSeconds={0}\n          rounds={item.targetSets}\n          roundRestSeconds={QUICK_CHRONO_REST_SECONDS}\n          onComplete={() => onExerciseChronoComplete(item)}\n          onCancel={() => setRunner(null)}\n        />\n      </div>\n    );\n  }\n\n  if (runner?.type === "circuit") {\n    const item = runner.item;\n    return (\n      <div className="max-w-md mx-auto">\n        <CircuitRunner\n          items={item.items.map((i) => ({ name: i.name }))}\n          workSeconds={item.workSeconds}\n          restSeconds={item.restSeconds}\n          rounds={item.rounds}\n          roundRestSeconds={item.roundRestSeconds}\n          onComplete={(duration) => onCircuitComplete(item, duration)}\n          onCancel={() => setRunner(null)}\n        />\n      </div>\n    );\n  }\n\n  const doneCount = (items?.filter((i) => i.done).length ?? 0) + circuits.filter((c) => c.done).length;\n  const total = (items?.length ?? 0) + circuits.length;\n\n  return (\n    <div className="max-w-xl">\n      {celebrating.length > 0 && (\n        <div className="bg-accent/10 border border-accent rounded-xl p-4 mb-5">\n          {celebrating.map((b) => (\n            <p key={b.key} className="text-sm">\n              <span className="text-xl mr-2">{b.emoji}</span>\n              Nouveau badge : <span className="font-semibold">{b.name}</span> — {b.description}\n            </p>\n          ))}\n          <button onClick={() => setCelebrating([])} className="text-xs text-muted hover:text-text mt-2">\n            Fermer\n          </button>\n        </div>\n      )}\n\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Aujourd\'hui</h1>\n      <p className="text-muted text-sm mb-6">\n        {total === 0\n          ? "Rien de prevu aujourd\'hui."\n          : `${doneCount} / ${total} seance${total > 1 ? "s" : ""} validee${doneCount > 1 ? "s" : ""}.`}\n      </p>\n\n      {items === null && <p className="text-muted">Chargement...</p>}\n\n      {items?.length === 0 && circuits.length === 0 && (\n        <div className="bg-surface border border-dashed border-border rounded-xl p-8 text-center">\n          <p className="text-muted text-sm mb-3">\n            Aucun exercice programme pour aujourd\'hui. Va voir tes camps pour rejoindre ou creer un camp.\n          </p>\n          <Link to="/camps" className="text-accent hover:text-accentSoft text-sm">\n            Voir mes camps\n          </Link>\n        </div>\n      )}\n\n      {circuits.length > 0 && (\n        <div className="space-y-3 mb-4">\n          {circuits.map((c) => (\n            <div\n              key={c.campCircuitId}\n              className={`bg-surface border rounded-xl p-4 ${c.done ? "border-success/50" : "border-border"}`}\n            >\n              <div className="flex items-center justify-between gap-3 flex-wrap">\n                <div>\n                  <p className="font-medium">🔁 {c.name}</p>\n                  <p className="text-xs text-muted">\n                    {c.campName} · {c.rounds} tour{c.rounds > 1 ? "s" : ""} · {c.items.length} exercice\n                    {c.items.length > 1 ? "s" : ""}\n                  </p>\n                  {c.description && <p className="text-xs text-muted italic mt-0.5">"{c.description}"</p>}\n                </div>\n                {c.done ? (\n                  <span className="text-success text-sm shrink-0">✓ Fait</span>\n                ) : (\n                  <button\n                    onClick={() => setRunner({ type: "circuit", item: c })}\n                    className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-4 py-2 text-sm shrink-0"\n                  >\n                    ⏱ Lancer\n                  </button>\n                )}\n              </div>\n            </div>\n          ))}\n        </div>\n      )}\n\n      <div className="space-y-3">\n        {items?.map((item) => {\n          const unitLabel = item.unit === "REPS" ? "reps" : "sec";\n          const isEditing = editingId === item.campExerciseId;\n          const canQuickChrono = item.unit === "SECONDS" && item.targetMode === "FIXED" && !item.done;\n          const targetLabel =\n            item.targetMode === "MAX"\n              ? `${item.targetSets} serie${item.targetSets > 1 ? "s" : ""} a fond${\n                  item.personalBest\n                    ? ` (record : ${item.unit === "SECONDS" ? secondsToMMSS(item.personalBest) : item.personalBest} ${unitLabel})`\n                    : ""\n                }`\n              : `${item.targetSets} x ${item.unit === "SECONDS" && item.targetValue ? secondsToMMSS(item.targetValue) : item.targetValue} ${item.unit === "SECONDS" ? "" : unitLabel}`;\n\n          return (\n            <div\n              key={item.campExerciseId}\n              className={`bg-surface border rounded-xl p-4 transition-colors ${\n                item.done ? "border-success/50" : "border-border"\n              }`}\n            >\n              <div className="flex items-center justify-between gap-3 flex-wrap">\n                <div>\n                  <p className="font-medium">{item.exerciseName}</p>\n                  <p className="text-xs text-muted">\n                    {item.campName} · objectif {targetLabel}\n                  </p>\n                  {item.description && <p className="text-xs text-muted italic mt-0.5">"{item.description}"</p>}\n                </div>\n\n                {!isEditing && (\n                  <div className="flex items-center gap-2 shrink-0">\n                    {canQuickChrono && (\n                      <button\n                        onClick={() => setRunner({ type: "exercise", item })}\n                        title="Lancer le chrono pour cet exercice"\n                        className="w-10 h-10 rounded-full flex items-center justify-center border-2 border-accent text-accent hover:bg-accent/10"\n                      >\n                        ⏱\n                      </button>\n                    )}\n                    <button\n                      onClick={() => (item.done ? undo(item) : startEditing(item))}\n                      className={`stamp-btn w-12 h-12 rounded-full flex items-center justify-center text-lg font-bold border-2 ${\n                        item.done\n                          ? "bg-success/20 border-success text-success"\n                          : "bg-surface2 border-border text-muted hover:border-accent hover:text-accent"\n                      }`}\n                      aria-label={item.done ? "Annuler la validation" : "Valider la seance"}\n                      title={item.done ? "Fait - clique pour annuler" : "Marquer comme fait"}\n                    >\n                      {item.done ? "✓" : ""}\n                    </button>\n                  </div>\n                )}\n              </div>\n\n              {item.done && item.log && (\n                <p className="text-xs text-muted mt-2">\n                  Realise : {item.log.setsDone} x{" "}\n                  {item.unit === "SECONDS" ? secondsToMMSS(item.log.valueDone) : `${item.log.valueDone} ${unitLabel}`}\n                </p>\n              )}\n\n              {isEditing && (\n                <div className="mt-3 flex items-end gap-3 flex-wrap bg-surface2 border border-border rounded-md p-3">\n                  <div>\n                    <label className="block text-xs text-muted mb-1">Series faites</label>\n                    <input\n                      type="number"\n                      min={0}\n                      value={sets}\n                      onChange={(e) => setSets(Number(e.target.value))}\n                      className="w-20 bg-surface border border-border rounded-md px-2 py-1"\n                    />\n                  </div>\n                  <div>\n                    <label className="block text-xs text-muted mb-1">{unitLabel} par serie</label>\n                    {item.unit === "SECONDS" ? (\n                      <DurationInput totalSeconds={value} onChange={setValue} />\n                    ) : (\n                      <input\n                        type="number"\n                        min={0}\n                        value={value}\n                        onChange={(e) => setValue(Number(e.target.value))}\n                        className="w-20 bg-surface border border-border rounded-md px-2 py-1"\n                      />\n                    )}\n                  </div>\n                  <button\n                    onClick={() => confirm(item)}\n                    className="bg-accent text-bg font-semibold rounded-md px-4 py-1.5 text-sm"\n                  >\n                    Valider\n                  </button>\n                  <button onClick={() => setEditingId(null)} className="text-muted text-sm px-2">\n                    Annuler\n                  </button>\n                </div>\n              )}\n            </div>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/CampDetail.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link, useNavigate, useParams } from "react-router-dom";\nimport { api } from "../api/client";\nimport { useAuth } from "../context/AuthContext";\nimport ProgramForm, { Program } from "../components/ProgramForm";\nimport CampCircuitForm, { CampCircuitData } from "../components/CampCircuitForm";\nimport CircuitRunner from "../components/CircuitRunner";\nimport { secondsToMMSS } from "../lib/duration";\n\ninterface CampExerciseData extends Program {\n  exercise: { id: string; name: string; unit: "REPS" | "SECONDS"; description: string | null };\n}\n\ninterface CampDetailData {\n  id: string;\n  name: string;\n  description: string | null;\n  code: string;\n  createdById: string;\n  startDate: string | null;\n  endDate: string | null;\n  exercises: CampExerciseData[];\n  circuits: CampCircuitData[];\n  members: { user: { id: string; name: string } }[];\n}\n\ninterface CatalogExercise {\n  id: string;\n  name: string;\n}\n\nconst RECURRENCE_LABEL: Record<string, (p: { recurrenceType: string; daysOfWeek: string | null; intervalDays: number | null }) => string> = {\n  DAILY: () => "Tous les jours",\n  WEEKLY: (p) => {\n    const days = p.daysOfWeek ? (JSON.parse(p.daysOfWeek) as number[]) : [];\n    const names = ["Dim", "Lun", "Mar", "Mer", "Jeu", "Ven", "Sam"];\n    return days.map((d) => names[d]).join(", ");\n  },\n  EVERY_N_DAYS: (p) => `Tous les ${p.intervalDays} jours`,\n};\n\nconst QUICK_CHRONO_REST_SECONDS = 15;\n\nexport default function CampDetail() {\n  const { id } = useParams<{ id: string }>();\n  const navigate = useNavigate();\n  const { user } = useAuth();\n  const [camp, setCamp] = useState<CampDetailData | null>(null);\n  const [catalog, setCatalog] = useState<CatalogExercise[]>([]);\n  const [editingExerciseId, setEditingExerciseId] = useState<string | null>(null);\n  const [editingDescription, setEditingDescription] = useState(false);\n  const [descriptionDraft, setDescriptionDraft] = useState("");\n  const [savingDescription, setSavingDescription] = useState(false);\n  const [confirmingDelete, setConfirmingDelete] = useState(false);\n  const [deleting, setDeleting] = useState(false);\n  const [editingCircuitId, setEditingCircuitId] = useState<string | null>(null);\n  const [creatingCircuit, setCreatingCircuit] = useState(false);\n  const [runningCircuit, setRunningCircuit] = useState<CampCircuitData | null>(null);\n  const [runningExercise, setRunningExercise] = useState<CampExerciseData | null>(null);\n\n  function load() {\n    if (!id) return;\n    api.get<CampDetailData>(`/camps/${id}`).then(setCamp);\n  }\n  useEffect(load, [id]);\n  useEffect(() => {\n    api.get<CatalogExercise[]>("/exercises").then(setCatalog);\n  }, []);\n\n  async function deleteCamp() {\n    if (!camp) return;\n    setDeleting(true);\n    try {\n      await api.del(`/camps/${camp.id}`);\n      navigate("/camps");\n    } finally {\n      setDeleting(false);\n    }\n  }\n\n  async function saveDescription() {\n    if (!camp) return;\n    setSavingDescription(true);\n    try {\n      await api.put(`/camps/${camp.id}`, { description: descriptionDraft.trim() || null });\n      setEditingDescription(false);\n      load();\n    } finally {\n      setSavingDescription(false);\n    }\n  }\n\n  async function deleteCircuit(circuitId: string) {\n    await api.del(`/camp-circuits/${circuitId}`);\n    load();\n  }\n\n  async function onExerciseChronoComplete(ce: CampExerciseData) {\n    await api.post("/logs", { campId: id, exerciseId: ce.exercise.id, setsDone: ce.targetSets, valueDone: ce.targetValue ?? 0 });\n    setRunningExercise(null);\n    load();\n  }\n\n  async function onCircuitChronoComplete(circuit: CampCircuitData, totalDurationSeconds: number) {\n    await api.post(`/camp-circuits/${circuit.id}/log`, { durationSeconds: totalDurationSeconds });\n    setRunningCircuit(null);\n    load();\n  }\n\n  if (!camp) return <p className="text-muted">Chargement...</p>;\n\n  const isCoach = user?.id === camp.createdById;\n\n  if (runningExercise) {\n    return (\n      <div className="max-w-md mx-auto">\n        <CircuitRunner\n          items={[{ name: runningExercise.exercise.name }]}\n          workSeconds={runningExercise.targetValue ?? 30}\n          restSeconds={0}\n          rounds={runningExercise.targetSets}\n          roundRestSeconds={QUICK_CHRONO_REST_SECONDS}\n          onComplete={() => onExerciseChronoComplete(runningExercise)}\n          onCancel={() => setRunningExercise(null)}\n        />\n      </div>\n    );\n  }\n\n  if (runningCircuit) {\n    const circuitItems = JSON.parse(runningCircuit.items) as { name: string }[];\n    return (\n      <div className="max-w-md mx-auto">\n        <CircuitRunner\n          items={circuitItems}\n          workSeconds={runningCircuit.workSeconds}\n          restSeconds={runningCircuit.restSeconds}\n          rounds={runningCircuit.rounds}\n          roundRestSeconds={runningCircuit.roundRestSeconds}\n          onComplete={(duration) => onCircuitChronoComplete(runningCircuit, duration)}\n          onCancel={() => setRunningCircuit(null)}\n        />\n      </div>\n    );\n  }\n\n  return (\n    <div className="max-w-2xl">\n      <div className="flex items-start justify-between flex-wrap gap-3 mb-2">\n        <div>\n          <h1 className="font-display text-3xl uppercase tracking-wide">{camp.name}</h1>\n          <p className="text-muted text-sm">\n            {camp.members.length} membre{camp.members.length > 1 ? "s" : ""} :{" "}\n            {camp.members.map((m) => m.user.name).join(", ")}\n          </p>\n          {(camp.startDate || camp.endDate) && (\n            <p className="text-muted text-xs mt-1">\n              {camp.startDate ? `Du ${new Date(camp.startDate).toLocaleDateString("fr-FR")}` : "Sans date de debut"}\n              {camp.endDate ? ` au ${new Date(camp.endDate).toLocaleDateString("fr-FR")}` : ""}\n            </p>\n          )}\n        </div>\n        <div className="bg-surface border border-border rounded-md px-3 py-2 text-center">\n          <p className="text-[10px] uppercase tracking-widest text-muted">Code</p>\n          <p className="font-mono text-lg text-accent">{camp.code}</p>\n        </div>\n      </div>\n\n      <div className="flex items-center gap-4 flex-wrap mt-2">\n        <Link to={`/camps/${camp.id}/discussion`} className="text-sm text-accent hover:text-accentSoft">\n          💬 Discussion du camp\n        </Link>\n        <Link to={`/camps/${camp.id}/classement`} className="text-sm text-accent hover:text-accentSoft">\n          📊 Classement (regularite)\n        </Link>\n        {isCoach && (\n          <button onClick={() => setConfirmingDelete(true)} className="text-sm text-muted hover:text-accent ml-auto">\n            Supprimer le camp\n          </button>\n        )}\n      </div>\n\n      {confirmingDelete && (\n        <div className="bg-surface border border-accent rounded-lg p-4 mt-3">\n          <p className="text-sm mb-3">\n            Supprimer definitivement le camp "{camp.name}" ? Cette action est irreversible : l\'historique des\n            seances de tous les membres pour ce camp sera perdu.\n          </p>\n          <div className="flex gap-2">\n            <button\n              onClick={deleteCamp}\n              disabled={deleting}\n              className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-3 py-1.5 text-sm disabled:opacity-60"\n            >\n              {deleting ? "Suppression..." : "Oui, supprimer"}\n            </button>\n            <button onClick={() => setConfirmingDelete(false)} className="text-muted hover:text-text text-sm px-2">\n              Annuler\n            </button>\n          </div>\n        </div>\n      )}\n\n      <div className="mt-4">\n        {editingDescription ? (\n          <div className="bg-surface2 border border-border rounded-lg p-3">\n            <textarea\n              value={descriptionDraft}\n              onChange={(e) => setDescriptionDraft(e.target.value)}\n              placeholder="Descriptif du camp..."\n              rows={3}\n              className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm resize-none mb-2"\n            />\n            <div className="flex gap-2">\n              <button\n                onClick={saveDescription}\n                disabled={savingDescription}\n                className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-3 py-1.5 text-sm disabled:opacity-60"\n              >\n                {savingDescription ? "Enregistrement..." : "Enregistrer"}\n              </button>\n              <button onClick={() => setEditingDescription(false)} className="text-muted hover:text-text text-sm px-2">\n                Annuler\n              </button>\n            </div>\n          </div>\n        ) : camp.description ? (\n          <div className="flex items-start justify-between gap-3">\n            <p className="text-sm text-muted italic">{camp.description}</p>\n            {isCoach && (\n              <button\n                onClick={() => {\n                  setDescriptionDraft(camp.description ?? "");\n                  setEditingDescription(true);\n                }}\n                className="text-xs text-accent hover:text-accentSoft shrink-0"\n              >\n                Modifier\n              </button>\n            )}\n          </div>\n        ) : (\n          isCoach && (\n            <button\n              onClick={() => {\n                setDescriptionDraft("");\n                setEditingDescription(true);\n              }}\n              className="text-xs text-accent hover:text-accentSoft"\n            >\n              + Ajouter un descriptif au camp\n            </button>\n          )\n        )}\n      </div>\n\n      <h2 className="font-display uppercase tracking-wide text-lg mt-8 mb-1">Exercices du camp</h2>\n      <p className="text-muted text-sm mb-4">\n        {isCoach\n          ? "En tant que createur du camp, tu definis la consigne (objectif, frequence) suivie par tous les membres."\n          : "Consignes definies par le createur du camp."}\n      </p>\n\n      <div className="space-y-3">\n        {camp.exercises.map((ce) => {\n          const isEditing = editingExerciseId === ce.exercise.id;\n\n          if (isEditing) {\n            return (\n              <ProgramForm\n                key={ce.exercise.id}\n                campId={camp.id}\n                exerciseId={ce.exercise.id}\n                exerciseName={ce.exercise.name}\n                unit={ce.exercise.unit}\n                existing={ce}\n                onSaved={() => {\n                  setEditingExerciseId(null);\n                  load();\n                }}\n                onCancel={() => setEditingExerciseId(null)}\n              />\n            );\n          }\n\n          const unitLabel = ce.exercise.unit === "REPS" ? "reps" : "";\n          const valueLabel =\n            ce.exercise.unit === "SECONDS" && ce.targetValue != null\n              ? secondsToMMSS(ce.targetValue)\n              : `${ce.targetValue} ${unitLabel}`;\n          const canQuickChrono = ce.exercise.unit === "SECONDS" && ce.targetMode === "FIXED";\n\n          return (\n            <div key={ce.exercise.id} className="bg-surface border border-border rounded-lg p-4">\n              <div className="flex items-center justify-between flex-wrap gap-3">\n                <div>\n                  <p className="font-medium">{ce.exercise.name}</p>\n                  <p className="text-sm text-muted">\n                    {ce.targetMode === "MAX"\n                      ? `${ce.targetSets} serie${ce.targetSets > 1 ? "s" : ""} a fond`\n                      : `${ce.targetSets} x ${valueLabel}`}{" "}\n                    · {RECURRENCE_LABEL[ce.recurrenceType](ce)}\n                  </p>\n                  {ce.description && <p className="text-xs text-muted mt-1 italic">"{ce.description}"</p>}\n                </div>\n                <div className="flex gap-3 items-center shrink-0">\n                  {canQuickChrono && (\n                    <button\n                      onClick={() => setRunningExercise(ce)}\n                      title="Lancer le chrono pour cet exercice"\n                      className="w-9 h-9 rounded-full flex items-center justify-center border-2 border-accent text-accent hover:bg-accent/10"\n                    >\n                      ⏱\n                    </button>\n                  )}\n                  <Link\n                    to={`/camps/${camp.id}/progression/${ce.exercise.id}`}\n                    className="text-sm text-accent hover:text-accentSoft"\n                  >\n                    Progression\n                  </Link>\n                  {isCoach && (\n                    <button\n                      onClick={() => setEditingExerciseId(ce.exercise.id)}\n                      className="text-sm bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-1.5"\n                    >\n                      Modifier\n                    </button>\n                  )}\n                </div>\n              </div>\n            </div>\n          );\n        })}\n      </div>\n\n      <div className="flex items-center justify-between mt-8 mb-1">\n        <h2 className="font-display uppercase tracking-wide text-lg">Circuits training du camp</h2>\n        {isCoach && !creatingCircuit && (\n          <button onClick={() => setCreatingCircuit(true)} className="text-sm text-accent hover:text-accentSoft">\n            + Nouveau circuit\n          </button>\n        )}\n      </div>\n      <p className="text-muted text-sm mb-4">\n        Enchainements guides au chrono, alternative aux exercices individuels.\n      </p>\n\n      {creatingCircuit && (\n        <div className="mb-3">\n          <CampCircuitForm\n            campId={camp.id}\n            catalog={catalog}\n            onSaved={() => {\n              setCreatingCircuit(false);\n              load();\n            }}\n            onCancel={() => setCreatingCircuit(false)}\n          />\n        </div>\n      )}\n\n      <div className="space-y-3">\n        {camp.circuits.map((circuit) => {\n          if (editingCircuitId === circuit.id) {\n            return (\n              <CampCircuitForm\n                key={circuit.id}\n                campId={camp.id}\n                catalog={catalog}\n                existing={circuit}\n                onSaved={() => {\n                  setEditingCircuitId(null);\n                  load();\n                }}\n                onCancel={() => setEditingCircuitId(null)}\n              />\n            );\n          }\n          const circuitItems = JSON.parse(circuit.items) as { name: string }[];\n          return (\n            <div key={circuit.id} className="bg-surface border border-border rounded-lg p-4">\n              <div className="flex items-center justify-between flex-wrap gap-3">\n                <div>\n                  <p className="font-medium">🔁 {circuit.name}</p>\n                  <p className="text-sm text-muted">\n                    {circuitItems.map((i) => i.name).join(", ")} · {circuit.rounds} tour{circuit.rounds > 1 ? "s" : ""} ·{" "}\n                    {RECURRENCE_LABEL[circuit.recurrenceType](circuit)}\n                  </p>\n                  {circuit.description && <p className="text-xs text-muted mt-1 italic">"{circuit.description}"</p>}\n                </div>\n                <div className="flex gap-2 items-center shrink-0">\n                  <button\n                    onClick={() => setRunningCircuit(circuit)}\n                    className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-3 py-1.5 text-sm"\n                  >\n                    ⏱ Lancer\n                  </button>\n                  {isCoach && (\n                    <>\n                      <button\n                        onClick={() => setEditingCircuitId(circuit.id)}\n                        className="text-sm bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-1.5"\n                      >\n                        Modifier\n                      </button>\n                      <button onClick={() => deleteCircuit(circuit.id)} className="text-muted hover:text-accent text-sm">\n                        Suppr.\n                      </button>\n                    </>\n                  )}\n                </div>\n              </div>\n            </div>\n          );\n        })}\n        {camp.circuits.length === 0 && !creatingCircuit && (\n          <p className="text-muted text-sm italic">Aucun circuit pour l\'instant.</p>\n        )}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/ActivityHistory.tsx'] = 'import { useEffect, useState } from "react";\nimport { api } from "../api/client";\nimport { secondsToMMSS } from "../lib/duration";\n\ninterface Stats {\n  totalSessions: number;\n  totalPracticeSeconds: number;\n  exerciseCount: number;\n  personalBests: { exerciseName: string; unit: string; best: number }[];\n}\n\ntype ActivityItem =\n  | { type: "exercise"; date: string; exerciseName: string; unit: "REPS" | "SECONDS"; campName: string; setsDone: number; valueDone: number }\n  | { type: "circuit"; date: string; circuitName: string; campName: string; durationSeconds: number }\n  | { type: "chrono"; date: string; name: string | null; items: string[]; totalDurationSeconds: number; rounds: number };\n\nfunction formatDuration(totalSeconds: number): string {\n  const h = Math.floor(totalSeconds / 3600);\n  const m = Math.round((totalSeconds % 3600) / 60);\n  if (h === 0) return `${m} min`;\n  return `${h} h ${m.toString().padStart(2, "0")}`;\n}\n\nexport default function ActivityHistory() {\n  const [stats, setStats] = useState<Stats | null>(null);\n  const [items, setItems] = useState<ActivityItem[] | null>(null);\n\n  useEffect(() => {\n    api.get<{ stats: Stats; items: ActivityItem[] }>("/activity").then((res) => {\n      setStats(res.stats);\n      setItems(res.items);\n    });\n  }, []);\n\n  return (\n    <div className="max-w-2xl">\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Mon historique</h1>\n      <p className="text-muted text-sm mb-6">Toutes tes seances, tous camps et circuits confondus.</p>\n\n      {stats && (\n        <div className="grid grid-cols-3 gap-3 mb-6">\n          <div className="bg-surface border border-border rounded-xl p-4 text-center">\n            <p className="font-display text-2xl text-accent">{stats.totalSessions}</p>\n            <p className="text-[10px] text-muted uppercase tracking-wide mt-1">Seances au total</p>\n          </div>\n          <div className="bg-surface border border-border rounded-xl p-4 text-center">\n            <p className="font-display text-2xl text-accent">{formatDuration(stats.totalPracticeSeconds)}</p>\n            <p className="text-[10px] text-muted uppercase tracking-wide mt-1">Temps de pratique</p>\n          </div>\n          <div className="bg-surface border border-border rounded-xl p-4 text-center">\n            <p className="font-display text-2xl text-accent">{stats.exerciseCount}</p>\n            <p className="text-[10px] text-muted uppercase tracking-wide mt-1">Exercices differents</p>\n          </div>\n        </div>\n      )}\n\n      {stats && stats.personalBests.length > 0 && (\n        <div className="bg-surface border border-border rounded-xl p-4 mb-6">\n          <h2 className="font-display uppercase tracking-wide text-sm mb-3">Records personnels (sur une serie)</h2>\n          <div className="grid sm:grid-cols-2 gap-2">\n            {stats.personalBests.map((pb) => (\n              <div key={pb.exerciseName} className="flex items-center justify-between text-sm">\n                <span className="text-muted">{pb.exerciseName}</span>\n                <span className="font-mono text-accent">\n                  {pb.unit === "SECONDS" ? secondsToMMSS(pb.best) : `${pb.best} reps`}\n                </span>\n              </div>\n            ))}\n          </div>\n        </div>\n      )}\n\n      <h2 className="font-display uppercase tracking-wide text-sm mb-3">Journal des seances</h2>\n\n      {items === null && <p className="text-muted">Chargement...</p>}\n      {items?.length === 0 && <p className="text-muted text-sm">Aucune seance enregistree pour l\'instant.</p>}\n\n      <div className="space-y-2">\n        {items?.map((item, index) => (\n          <div key={index} className="bg-surface border border-border rounded-lg p-3 flex items-center justify-between gap-3">\n            <div>\n              {item.type === "exercise" && (\n                <>\n                  <p className="text-sm font-medium">{item.exerciseName}</p>\n                  <p className="text-xs text-muted">\n                    {item.campName} · {item.setsDone} x{" "}\n                    {item.unit === "SECONDS" ? secondsToMMSS(item.valueDone) : `${item.valueDone} reps`}\n                  </p>\n                </>\n              )}\n              {item.type === "circuit" && (\n                <>\n                  <p className="text-sm font-medium">🔁 {item.circuitName}</p>\n                  <p className="text-xs text-muted">\n                    {item.campName} · {formatDuration(item.durationSeconds)}\n                  </p>\n                </>\n              )}\n              {item.type === "chrono" && (\n                <>\n                  <p className="text-sm font-medium">⏱ {item.name || "Circuit libre"}</p>\n                  <p className="text-xs text-muted">\n                    {item.items.join(", ")} · {item.rounds} tour{item.rounds > 1 ? "s" : ""} ·{" "}\n                    {formatDuration(item.totalDurationSeconds)}\n                  </p>\n                </>\n              )}\n            </div>\n            <p className="text-xs text-muted shrink-0">\n              {new Date(item.date).toLocaleDateString("fr-FR", { day: "2-digit", month: "short" })}\n            </p>\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/components/Layout.tsx'] = 'import { NavLink, useNavigate } from "react-router-dom";\nimport { ReactNode } from "react";\nimport { useAuth } from "../context/AuthContext";\n\nconst desktopNavItems = [\n  { to: "/aujourdhui", label: "Aujourd\'hui" },\n  { to: "/camps", label: "Mes camps" },\n  { to: "/chrono", label: "Chrono" },\n  { to: "/exercices", label: "Exercices" },\n  { to: "/messages", label: "Messages" },\n  { to: "/historique", label: "Historique" },\n  { to: "/profil", label: "Profil" },\n];\n\n// Sur mobile, la barre du bas ne montre que l\'essentiel : le Chrono a sa propre bulle\n// centrale, les autres onglets (Exercices, Historique) restent accessibles depuis le menu\n// complet sur ordinateur, ou via des liens dans "Mes camps" / "Profil" sur mobile.\nconst mobileLeftItems = [\n  { to: "/aujourdhui", label: "Aujourd\'hui", icon: "📅" },\n  { to: "/camps", label: "Camps", icon: "🏕️" },\n];\nconst mobileRightItems = [\n  { to: "/messages", label: "Messages", icon: "💬" },\n  { to: "/profil", label: "Profil", icon: "👤" },\n];\n\nexport default function Layout({ children }: { children: ReactNode }) {\n  const { user, logout } = useAuth();\n  const navigate = useNavigate();\n\n  return (\n    <div className="min-h-screen flex flex-col md:flex-row">\n      <header className="md:w-64 md:min-h-screen border-b md:border-b-0 md:border-r border-border bg-surface flex md:flex-col justify-between">\n        <div className="p-6">\n          <div className="flex items-center gap-2 mb-8">\n            <img src="/logo-mark.png" alt="" className="w-8 h-8 object-contain" />\n            <span className="font-display text-lg tracking-wide uppercase">GoTeam</span>\n          </div>\n          <nav className="hidden md:flex md:flex-col gap-1">\n            {desktopNavItems.map((item) => (\n              <NavLink\n                key={item.to}\n                to={item.to}\n                className={({ isActive }) =>\n                  `px-3 py-2 rounded-md text-sm font-medium transition-colors ${\n                    isActive ? "bg-accent/15 text-accent" : "text-muted hover:text-text hover:bg-surface2"\n                  }`\n                }\n              >\n                {item.label}\n              </NavLink>\n            ))}\n          </nav>\n        </div>\n        <div className="p-6 hidden md:block">\n          {user && <p className="text-xs text-muted mb-2 truncate">{user.name}</p>}\n          <button\n            onClick={() => {\n              logout();\n              navigate("/connexion");\n            }}\n            className="text-sm text-muted hover:text-accent transition-colors"\n          >\n            Se deconnecter\n          </button>\n        </div>\n      </header>\n\n      <main className="flex-1 p-5 pb-24 md:p-10 md:pb-10 max-w-4xl mx-auto w-full order-1">{children}</main>\n\n      {/* Barre de navigation mobile, fixee en bas, avec le Chrono en bulle centrale */}\n      <nav className="md:hidden fixed bottom-0 inset-x-0 bg-surface border-t border-border flex items-end justify-around pb-1 pt-2 z-40">\n        {mobileLeftItems.map((item) => (\n          <NavLink\n            key={item.to}\n            to={item.to}\n            className={({ isActive }) =>\n              `flex-1 flex flex-col items-center gap-0.5 py-1 text-[10px] font-medium ${\n                isActive ? "text-accent" : "text-muted"\n              }`\n            }\n          >\n            <span className="text-lg leading-none">{item.icon}</span>\n            {item.label}\n          </NavLink>\n        ))}\n\n        <NavLink to="/chrono" className="flex-1 flex flex-col items-center -mt-7">\n          {({ isActive }) => (\n            <>\n              <span\n                className={`w-14 h-14 rounded-full flex items-center justify-center text-2xl shadow-lg border-4 border-bg ${\n                  isActive ? "bg-accentSoft" : "bg-accent"\n                } text-bg`}\n              >\n                ⏱\n              </span>\n              <span className={`text-[10px] font-medium mt-0.5 ${isActive ? "text-accent" : "text-muted"}`}>\n                Chrono\n              </span>\n            </>\n          )}\n        </NavLink>\n\n        {mobileRightItems.map((item) => (\n          <NavLink\n            key={item.to}\n            to={item.to}\n            className={({ isActive }) =>\n              `flex-1 flex flex-col items-center gap-0.5 py-1 text-[10px] font-medium ${\n                isActive ? "text-accent" : "text-muted"\n              }`\n            }\n          >\n            <span className="text-lg leading-none">{item.icon}</span>\n            {item.label}\n          </NavLink>\n        ))}\n      </nav>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Profile.tsx'] = 'import { FormEvent, useEffect, useState } from "react";\nimport { Link } from "react-router-dom";\nimport { useAuth } from "../context/AuthContext";\nimport { api, ApiError } from "../api/client";\nimport { enablePushNotifications } from "../lib/push";\n\ninterface Badge {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n  earned: boolean;\n  earnedAt: string | null;\n}\n\nexport default function Profile() {\n  const { user, refreshUser } = useAuth();\n  const [weightKg, setWeightKg] = useState(user?.weightKg?.toString() ?? "");\n  const [heightCm, setHeightCm] = useState(user?.heightCm?.toString() ?? "");\n  const [birthDate, setBirthDate] = useState(user?.birthDate?.slice(0, 10) ?? "");\n  const [sex, setSex] = useState(user?.sex ?? "");\n  const [message, setMessage] = useState<string | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n  const [badges, setBadges] = useState<Badge[] | null>(null);\n\n  useEffect(() => {\n    api.get<Badge[]>("/badges").then(setBadges);\n  }, []);\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    setError(null);\n    setMessage(null);\n    setBusy(true);\n    try {\n      await api.put("/users/me", {\n        weightKg: weightKg ? Number(weightKg) : null,\n        heightCm: heightCm ? Number(heightCm) : null,\n        birthDate: birthDate || null,\n        sex: sex || null,\n      });\n      await refreshUser();\n      setMessage("Profil mis a jour.");\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Impossible de mettre a jour le profil.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  async function onEnableNotifications() {\n    setMessage(null);\n    setError(null);\n    try {\n      const result = await enablePushNotifications();\n      setMessage(result);\n    } catch {\n      setError("Impossible d\'activer les notifications sur cet appareil.");\n    }\n  }\n\n  return (\n    <div className="max-w-lg">\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Mon profil</h1>\n      <p className="text-muted text-sm mb-6">Ces infos sont juste pour toi, pas partagees avec les autres membres.</p>\n\n      <div className="flex gap-2 mb-6 md:hidden">\n        <Link\n          to="/exercices"\n          className="flex-1 text-center bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-2 text-sm"\n        >\n          📚 Exercices\n        </Link>\n        <Link\n          to="/historique"\n          className="flex-1 text-center bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-2 text-sm"\n        >\n          📈 Historique\n        </Link>\n      </div>\n\n      <form onSubmit={onSubmit} className="bg-surface border border-border rounded-xl p-6 space-y-4">\n        <div className="grid grid-cols-2 gap-4">\n          <div>\n            <label className="block text-sm text-muted mb-1" htmlFor="weight">\n              Poids (kg)\n            </label>\n            <input\n              id="weight"\n              type="number"\n              step="0.1"\n              min="0"\n              value={weightKg}\n              onChange={(e) => setWeightKg(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n            />\n          </div>\n          <div>\n            <label className="block text-sm text-muted mb-1" htmlFor="height">\n              Taille (cm)\n            </label>\n            <input\n              id="height"\n              type="number"\n              step="0.1"\n              min="0"\n              value={heightCm}\n              onChange={(e) => setHeightCm(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n            />\n          </div>\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-1" htmlFor="birthDate">\n            Date de naissance\n          </label>\n          <input\n            id="birthDate"\n            type="date"\n            value={birthDate}\n            onChange={(e) => setBirthDate(e.target.value)}\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n          />\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-1" htmlFor="sex">\n            Sexe (optionnel)\n          </label>\n          <select\n            id="sex"\n            value={sex}\n            onChange={(e) => setSex(e.target.value)}\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n          >\n            <option value="">Ne souhaite pas preciser</option>\n            <option value="F">Femme</option>\n            <option value="M">Homme</option>\n            <option value="AUTRE">Autre</option>\n          </select>\n        </div>\n\n        {message && <p className="text-sm text-success">{message}</p>}\n        {error && <p className="text-sm text-accent">{error}</p>}\n\n        <button\n          type="submit"\n          disabled={busy}\n          className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-5 py-2 disabled:opacity-60"\n        >\n          {busy ? "Enregistrement..." : "Enregistrer"}\n        </button>\n      </form>\n\n      <div className="bg-surface border border-border rounded-xl p-6 mt-6">\n        <h2 className="font-display text-lg uppercase tracking-wide mb-1">Rappels</h2>\n        <p className="text-muted text-sm mb-4">\n          Active les notifications pour recevoir un rappel les jours ou une seance est prevue.\n        </p>\n        <button\n          onClick={onEnableNotifications}\n          className="bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-4 py-2 text-sm"\n        >\n          Activer les notifications\n        </button>\n      </div>\n      <div className="bg-surface border border-border rounded-xl p-6 mt-6">\n        <h2 className="font-display text-lg uppercase tracking-wide mb-1">Mes badges</h2>\n        <p className="text-muted text-sm mb-4">\n          Bases sur ta regularite personnelle uniquement, pas de comparaison avec les autres membres.\n        </p>\n        {badges === null && <p className="text-muted text-sm">Chargement...</p>}\n        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">\n          {badges?.map((b) => (\n            <div\n              key={b.key}\n              title={b.description}\n              className={`rounded-lg p-3 text-center border ${\n                b.earned ? "bg-accent/10 border-accent" : "bg-surface2 border-border opacity-40"\n              }`}\n            >\n              <p className="text-2xl mb-1">{b.emoji}</p>\n              <p className="text-xs font-medium">{b.name}</p>\n            </div>\n          ))}\n        </div>\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/App.tsx'] = 'import { Navigate, Route, Routes } from "react-router-dom";\nimport { ReactNode } from "react";\nimport { useAuth } from "./context/AuthContext";\nimport Layout from "./components/Layout";\n\nimport Login from "./pages/Login";\nimport Register from "./pages/Register";\nimport Profile from "./pages/Profile";\nimport Dashboard from "./pages/Dashboard";\nimport CreateCamp from "./pages/CreateCamp";\nimport JoinCamp from "./pages/JoinCamp";\nimport CampDetail from "./pages/CampDetail";\nimport Today from "./pages/Today";\nimport Progress from "./pages/Progress";\nimport ExerciseRepository from "./pages/ExerciseRepository";\nimport CampChat from "./pages/CampChat";\nimport Messages from "./pages/Messages";\nimport CampLeaderboard from "./pages/CampLeaderboard";\nimport Chrono from "./pages/Chrono";\nimport ActivityHistory from "./pages/ActivityHistory";\n\nfunction Private({ children }: { children: ReactNode }) {\n  const { user, loading } = useAuth();\n  if (loading) return <div className="min-h-screen flex items-center justify-center text-muted">Chargement...</div>;\n  if (!user) return <Navigate to="/connexion" replace />;\n  return <Layout>{children}</Layout>;\n}\n\nexport default function App() {\n  return (\n    <Routes>\n      <Route path="/connexion" element={<Login />} />\n      <Route path="/inscription" element={<Register />} />\n\n      <Route path="/aujourdhui" element={<Private><Today /></Private>} />\n      <Route path="/profil" element={<Private><Profile /></Private>} />\n      <Route path="/camps" element={<Private><Dashboard /></Private>} />\n      <Route path="/camps/creer" element={<Private><CreateCamp /></Private>} />\n      <Route path="/camps/rejoindre" element={<Private><JoinCamp /></Private>} />\n      <Route path="/camps/:id" element={<Private><CampDetail /></Private>} />\n      <Route path="/camps/:id/progression/:exerciseId" element={<Private><Progress /></Private>} />\n      <Route path="/exercices" element={<Private><ExerciseRepository /></Private>} />\n      <Route path="/camps/:id/discussion" element={<Private><CampChat /></Private>} />\n      <Route path="/camps/:id/classement" element={<Private><CampLeaderboard /></Private>} />\n      <Route path="/chrono" element={<Private><Chrono /></Private>} />\n      <Route path="/historique" element={<Private><ActivityHistory /></Private>} />\n      <Route path="/messages" element={<Private><Messages /></Private>} />\n\n      <Route path="*" element={<Navigate to="/aujourdhui" replace />} />\n    </Routes>\n  );\n}\n'

for rel_path, content in FILES.items():
    p = pathlib.Path(rel_path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content, encoding='utf-8')
    print('OK ->', rel_path)

print()
